(window.TNQ=window.TNQ||[]).push({"terms":{"컷셋":{"d":"그 안의 기본사상이 모두 일어나면 정상사상이 일어나는 사상의 조합입니다.","r":[]},"샌드드레인":{"d":"연약 지반에 모래 기둥을 박아 물이 빠지는 길을 만드는 지반 개량 공법입니다.","r":[]},"중성화":{"d":"콘크리트 알칼리성이 탄산가스 때문에 떨어져 철근 부식을 쉽게 하는 현상입니다.","r":[]},"보일링":{"d":"사질지반에서 수위차 때문에 물과 모래가 굴착 바닥으로 솟아오르는 현상입니다.","r":[]},"언더피닝":{"d":"기존 건물 기초 가까이를 굴착할 때 기초를 밑에서 보강하는 공법입니다.","r":[]},"기경성":{"d":"공기 중의 이산화탄소와 반응해 굳는 성질입니다.","r":[]},"열경화성":{"d":"한 번 가열해 굳으면 다시 가열해도 물러지지 않는 수지의 성질입니다.","r":[]},"섬유포화점":{"d":"목재 세포벽은 물로 차 있고 빈 공간에는 자유수가 없는 상태의 함수율입니다.","r":[]},"연화점":{"d":"아스팔트가 열을 받아 물러지기 시작하는 온도입니다.","r":[]},"신도":{"d":"아스팔트 시료를 잡아당길 때 끊어지기 전까지 늘어나는 길이입니다.","r":[]},"감온성":{"d":"온도 변화에 따라 아스팔트의 굳기가 달라지는 성질입니다.","r":[]},"침입도":{"d":"표준 침이 아스팔트에 들어간 깊이로 굳기를 나타낸 값입니다.","r":[]},"컨시스턴시":{"d":"주로 수량에 따라 달라지는 반죽의 묽고 된 정도입니다.","r":[]},"워커빌리티":{"d":"굳지 않은 콘크리트를 재료분리 없이 다루기 쉬운 정도입니다.","r":["컨시스턴시"]},"블리딩":{"d":"굳기 전 콘크리트에서 물이 위로 떠오르는 재료분리 현상입니다.","r":[]},"물시멘트비":{"d":"콘크리트에서 시멘트 무게에 대한 물 무게의 비율입니다.","r":[]},"측압":{"d":"굳지 않은 콘크리트가 거푸집을 옆으로 미는 압력입니다.","r":["폼타이"]},"폼타이":{"d":"벽거푸집 양면을 조여 간격을 잡고 측압을 지지하는 긴결재입니다.","r":[]},"스페이서":{"d":"철근이 거푸집에 밀착되지 않도록 피복 두께를 유지하는 받침 부재입니다.","r":[]},"컬럼밴드":{"d":"기둥거푸집이 벌어지지 않도록 바깥에서 조이는 밴드입니다.","r":[]},"수평연결재":{"d":"동바리 기둥이 옆으로 흔들리지 않게 수평 방향으로 이어 주는 부재입니다.","r":[]},"띠장":{"d":"비계 기둥을 수평으로 연결하는 가로 부재입니다.","r":["장선"]},"장선":{"d":"비계 기둥 사이에 걸쳐 작업발판을 받치는 가로 부재입니다.","r":["띠장"]},"트레미":{"d":"수중에 콘크리트를 칠 때 쓰는 연직 관입니다.","r":[]},"크리프":{"d":"일정한 하중이 계속될 때 시간이 지나며 변형이 늘어나는 현상입니다.","r":[]},"건조수축":{"d":"콘크리트가 마르면서 수분이 빠져 부피가 줄어드는 현상입니다.","r":[]},"오토클레이브":{"d":"고온·고압 증기로 경화시키는 양생 장치입니다.","r":[]},"한중콘크리트":{"d":"하루 평균기온이 4℃ 이하일 때 동결을 막으려고 시공하는 콘크리트입니다.","r":[]},"수밀콘크리트":{"d":"물이 새지 않도록 물시멘트비를 낮춰 치밀하게 만든 콘크리트입니다.","r":[]},"AE제":{"d":"콘크리트에 미세한 공기 기포를 고르게 만드는 혼화제입니다.","r":[]},"종석":{"d":"인조석바름에서 표면에 드러나게 섞는 작은 돌입니다.","r":[]},"TWI":{"d":"현장 감독자를 대상으로 하는 작업지도, 작업방법, 인간관계 훈련 과정입니다.","r":[]},"헤드십":{"d":"임명으로 얻은 공식 권한에 의지해 이끄는 방식입니다.","r":["리더십"]},"리더십":{"d":"집단 구성원의 동의로 권한을 얻어 이끄는 방식입니다.","r":["헤드십"]},"위생요인":{"d":"충족되지 않으면 불만을 일으키는 보수, 작업조건 같은 요인입니다.","r":[]},"FMEA":{"d":"부품의 고장 형태가 시스템에 미치는 영향을 따져 보는 정성적 분석법입니다.","r":["FTA"]},"FTA":{"d":"정상사상에서 원인을 거슬러 올라가는 연역적 고장 분석 기법입니다.","r":["FMEA"]},"THERP":{"d":"작업자 오류 확률을 추정해 인간 신뢰도를 분석하는 기법입니다.","r":[]},"실효온도":{"d":"온도, 습도, 기류를 합쳐 사람이 느끼는 온감을 나타낸 지수입니다.","r":[]},"조도":{"d":"물체나 표면에 도달하는 빛의 밀도입니다.","r":["휘도"]},"휘도":{"d":"광원이나 표면이 단위 면적당 내는 밝기입니다.","r":["조도"]},"생략 오류":{"d":"해야 할 작업을 하지 않고 빠뜨린 오류입니다.","r":[]},"우발고장":{"d":"불규칙하게 일어나며 고장률이 시간과 무관하게 일정한 고장입니다.","r":[]},"권과방지장치":{"d":"훅이나 달기구가 너무 높이 감겨 올라가 부딪히지 않도록 막는 장치입니다.","r":[]},"과부하방지장치":{"d":"정격하중을 넘는 하중이 걸리면 작동을 막거나 경보를 내는 장치입니다.","r":[]},"정격하중":{"d":"권상하중에서 달기구 무게를 뺀, 크레인이 실제로 매달 수 있는 최대 하중입니다.","r":[]},"엔드탭":{"d":"용접 시작과 끝의 결함을 막으려고 이음부 양 끝에 붙이는 보조판입니다.","r":[]},"가볼트":{"d":"철골 부재를 본접합하기 전에 임시로 조립하는 볼트입니다.","r":[]},"고장력볼트":{"d":"높은 인장강도를 가진 볼트로 철골 접합에 마찰력으로 힘을 전달합니다.","r":[]},"녹막이칠":{"d":"철골 표면이 녹슬지 않도록 바르는 방청 도장입니다.","r":[]},"띠쇠":{"d":"목구조 접합부의 인장력을 보강하는 띠 모양 철물입니다.","r":[]}},"notes":{"0.5~1초 지속하고 배경소음과 다른 주파수를 쓴다":"청각 신호는 0.5~1초 길이로 내고 배경소음과 다른 주파수를 씁니다.","1000Hz에서 120dB이면 120phon이고 256sone이다":"1000Hz에서 120dB 소리는 120phon으로 환산되고 그때 256sone에 해당합니다.","100Hz 이하 낮은 주파수에 덜 민감하고 높은 주파수에 더 민감하다":"100Hz 아래 낮은 소리에는 귀가 덜 민감하고 높은 소리에는 더 민감합니다.","100℃ 이상에서 일산화탄소·메탄·수소 같은 가연성 가스가 나온다":"목재를 100℃ 이상으로 데우면 일산화탄소, 메탄, 수소 같은 가연성 가스가 나옵니다.","100명 이상 사업장에 적합하고 안전업무를 전담해 기술 축적이 쉽다":"스태프형은 100명 이상 사업장에 맞고 안전업무를 전담해 기술을 쌓기 쉽습니다.","13단 이하 높이로 쌓고 저장기간을 짧게 한다":"시멘트는 13단 넘게 쌓지 않고 오래 두지 않도록 저장기간을 짧게 잡습니다.","1lux는 1촉광 점광원에서 1m, 1fc는 1ft 떨어진 곡면의 광 밀도이다":"광 밀도는 1lux가 1촉광 점광원에서 1m 떨어진 곡면, 1fc가 1ft 떨어진 곡면에서 잰 값입니다.","1라운드는 현상파악이고 본질추구가 아니다. 전원이 대화 방식으로 진행하는 팀워크 훈련이다":"1라운드는 현상파악이며 전원이 대화로 진행하는 팀워크 훈련입니다.","1층 바닥을 조기 완성하고 지하·지상을 동시 시공하며 소음·진동은 작다":"탑다운은 1층 바닥을 먼저 완성하고 지하와 지상을 동시에 시공하며 소음·진동이 작습니다.","20m 초과 시 송기설비와 통신설비를 설치한다":"굴착깊이가 20m를 넘으면 송기설비와 통신설비를 설치합니다.","2^((phon값−40)/10)이다":"sone값은 phon값에서 40을 뺀 값을 10으로 나눈 수를 2의 지수로 올려 구합니다.","2라운드 위험요인(본질) 추구·결정":"위험예지훈련 2라운드는 위험요인을 찾고 본질을 추구해 핵심 위험을 정하는 단계입니다.","300이며 가장 많이 발생한다":"하인리히 비율에서 무상해사고는 300으로 가장 많이 발생합니다.","3단계가 정량적 평가이고 공정계통도는 2단계 진단 항목이 아니다":"정량적 평가는 3단계에서 하며, 공정계통도는 2단계에서 진단하는 항목에 들지 않습니다.","3본 이상 잇지 않고 이을 때 볼트 4개 이상 또는 전용철물을 쓴다":"파이프서포트는 3본 이상 이어 쓰지 않고, 이을 때 볼트 4개 이상이나 전용철물을 씁니다.","40세 이후 근시력 저하·망막 조명량 감소·수정체 변색이 생기고 휘광 민감도는 높아진다":"40세 이후에는 근시력이 떨어지고 망막 조명량이 줄며 수정체가 변색되고 휘광에 더 민감해집니다.","6단계 설계에서 3단계 기본설계에는 직무 분석이 들어간다":"6단계 설계 가운데 기본설계인 3단계에서 직무 분석을 합니다.","90°나 70° 정도로 하지 않는다":"매다는 각도를 90°나 70° 정도로 하는 것은 맞지 않습니다.","AE감수제 지연형 또는 감수제 지연형을 쓴다":"서중콘크리트에는 AE감수제 지연형 또는 감수제 지연형을 씁니다.","B는 행동, P는 개체(사람), E는 환경이다":"레윈의 행동방정식에서 B는 행동, P는 개체(사람), E는 환경입니다.","C1 기능적 고장 영향 중요도·C2 영향 시스템 범위·C3 고장발생 빈도이다":"FMEA 평가요소는 기능적 고장 영향 중요도 C1, 영향 시스템 범위 C2, 고장발생 빈도 C3입니다.","ETA·FMEA·THERP는 시스템 안전 기법이고 DYNAMO는 아니다":"시스템 안전 기법에는 ETA, FMEA, THERP가 있고 DYNAMO는 거기서 빠집니다.","FTA는 연역적·정량적 분석이 가능하고 PHA는 운용사고 해석이 아니다":"FTA는 연역적이고 정량 분석도 가능하며 PHA는 운용 사고를 해석하는 기법이 아닙니다.","FT를 먼저 작성한 뒤 정상사상의 발생확률을 구한다":"FT를 먼저 그린 다음에야 정상사상의 발생확률을 계산할 수 있습니다.","Fussell(MOCUS)·Boolean·Limnios & Ziani 알고리즘으로 구하고 Monte Carlo는 아니다":"Monte Carlo는 확률 모의 기법이어서 최소 컷셋을 구하는 알고리즘에 들지 않고 MOCUS 등이 쓰입니다.","ILO 분류에서 장해등급 제4급~제14급은 영구 일부노동 불능 상해이다":"ILO 분류에서 장해등급 4급부터 14급까지는 영구 일부노동 불능 상해에 해당합니다.","JMT는 작업개선 방법이고 JRT는 부하직원 통솔 기법이다":"작업개선 방법이 JMT이고 부하직원 통솔 기법이 JRT입니다.","Man·Machine·Media·Management이다":"사람(Man), 기계(Machine), 매체(Media), 관리(Management)가 재해의 기본원인으로 꼽힙니다.","Oxford 지수·실효온도·열 스트레스 지수가 있고 카타온도는 아니다":"카타온도는 복합지수가 아니고, Oxford 지수·실효온도·열 스트레스 지수가 복합지수입니다.","PC 조립 시 신호수를 지정하고 인양 부재 아래 근로자 출입을 금한다":"PC 조립 시에는 신호수를 정하고 인양 부재 아래로 근로자가 들어가지 못하게 합니다.","Primary·Secondary·Command error이다":"원인에 따른 휴먼에러 분류는 Primary, Secondary, Command error입니다.","Watson이 군용으로 처음 고안했고 AND 게이트 확률은 입력사상의 곱이다":"AND 게이트 확률은 입력사상 확률을 곱해 구하고, FTA는 Watson이 군용으로 처음 고안했습니다.","fail-safe·fool-proof 시스템이다":"신뢰도를 유지하는 방안은 fail-safe와 fool-proof 시스템입니다.","knob 반지름을 1cm에서 2cm로 바꾸면 C/R비는 2배 증가한다":"knob 반지름이 1cm에서 2cm로 커지면 C/R비가 두 배가 됩니다.","가공전선로에 닿으면 크레인에서 이탈해 뛰어내린 뒤 반대 방향으로 탈출한다":"가공전선로에 닿으면 크레인에서 뛰어내려 반대 방향으로 벗어나야 합니다.","가볼트는 많이 하거나 오래 두지 않으며 이음은 고장력볼트·리벳·용접이음이다":"가볼트를 많이 하거나 오래 두지 말고, 이음은 고장력볼트, 리벳, 용접으로 합니다.","가설구조물 강재화·기계화·프리패브화이며 습식화가 아니다":"시공은 가설구조물 강재화, 기계화, 프리패브화 쪽으로 발전하고 습식화는 아닙니다.","가설도로계획서와 보호장비 폐기계획은 첨부서류가 아니다":"첨부서류 목록에는 가설도로계획서와 보호장비 폐기계획이 없습니다.","가설·철거가 쉽고 내구성이 있어 전용이 가능하다":"강재 지보공은 설치와 철거가 쉽고 튼튼해 여러 번 다시 쓸 수 있습니다.","가설통로의 경사는 30도 이하로 하고 15도를 넘으면 미끄럼 방지 구조로 한다":"가설통로는 비탈이 30도 이하여야 하고, 15도를 넘는 경사면에는 미끄러지지 않도록 합니다.","가연성 가스 발생장치 취급과 건설용 리프트·곤돌라 작업도 대상이며 전압 50V·30V 정전·활선작업은 아니다":"리프트·곤돌라 작업과 가연성 가스 발생장치 취급은 대상이고, 50V·30V 정전·활선작업은 해당하지 않습니다.","가열·냉각으로 필요한 성질을 주는 조작이다":"열처리는 가열과 냉각으로 필요한 성질을 주는 조작입니다.","각 단계는 만족 후 다음 단계로 진행하고 욕구 발생은 중첩된다":"각 단계는 만족한 뒤 다음 단계로 넘어가며 욕구는 서로 겹쳐 생깁니다.","간극 속 물이 배수되며 오랜 시간 압축되는 현상이고 완료되면 과잉간극수압이 0이 된다":"압밀은 간극 속 물이 빠지며 오랜 시간 압축되는 현상이고 끝나면 과잉간극수압이 0이 됩니다.","간극 속 물이 빠지며 입자 간격이 좁아져 침하하는 현상이다":"압밀침하는 간극 속 물이 빠지며 입자 사이가 좁아져 가라앉는 현상입니다.","감지·정보보관(저장)·정보처리 및 의사결정·행동이다":"인간-기계 체계의 기본기능은 감지, 정보보관(저장), 정보처리 및 의사결정, 행동입니다.","강관은 2m 이내마다 수평연결재를 2개 방향으로 설치한다":"강관 동바리는 2m 이내마다 수평연결재를 두 방향으로 설치합니다.","강도가 적고 건조수축이 크며 물과 접하는 지하실에는 부적합하다":"경량콘크리트는 강도가 적고 건조수축이 커서 물과 닿는 지하실에는 맞지 않습니다.","강도는 비중이 클수록 크고 섬유포화점 이상에서는 함수율이 변해도 강도가 일정하다":"섬유포화점 위에서는 함수율이 변해도 강도가 그대로이고, 비중이 클수록 강도가 큽니다.","강의 열처리 방법은 불림·풀림·뜨임질(·담금질)이다":"강의 열처리 방법에는 불림, 풀림, 뜨임질, 담금질이 있습니다.","강의 팽창계수는 콘크리트와 유사하고 담금질은 경도를 높이며 내산성과는 무관하다":"강의 팽창계수는 콘크리트와 비슷하고 담금질은 경도를 높이지만 내산성과는 관계가 없습니다.","강제평판·슬럼프콘·다짐막대·측정기기이다":"슬럼프시험 기구는 강제평판, 슬럼프콘, 다짐막대, 측정기기입니다.","같은 가능성의 4개 대안 중 하나는 1bit가 아니다":"같은 가능성의 네 대안 중 하나가 정해질 때는 1bit보다 많은 정보를 얻습니다.","같은 가능성의 8개 대안 중 하나도 1bit가 아니다":"같은 가능성의 여덟 대안 중 하나가 정해질 때도 1bit가 아니라 더 큰 정보량입니다.","같은 세기의 고주파 음만큼 크게 들리지 않는다":"저주파 음은 같은 세기의 고주파 음만큼 크게 들리지 않습니다.","같은 위치에서 철근 수의 반 이상을 이어서는 안 되고 이음은 인장력이 작은 곳에 둔다":"같은 위치에서 철근 수의 반 이상을 잇지 않으며 이음은 인장력이 작은 곳에 둡니다.","같은 크기로 들리려면 저주파 음이 더 강해야 한다":"저주파 음이 같은 크기로 들리려면 소리가 더 강해야 합니다.","개구부 등 끊기 좋은 곳에서 하고 기둥을 중간에서 수평으로 잇지 않는다":"벽은 개구부처럼 끊기 좋은 곳에서 이어붓고 기둥을 중간에서 수평으로 잇지는 않습니다.","개인능력에 속하는 실수 요인은 긴장수준·피로상태·교육훈련이다":"긴장수준, 피로상태, 교육훈련이 개인능력에 해당하는 실수 요인입니다.","개폐를 신속히 하면 안 된다":"가스 밸브를 급히 여닫으면 위험하므로 신속히 개폐하지 않습니다.","거푸집 간격을 유지하고 오그라드는 것을 막는다":"세퍼레이터는 거푸집 간격을 유지하고 거푸집이 오그라드는 것을 막습니다.","거푸집의 소형화는 발전 방향이 아니다":"거푸집을 작게 만드는 것은 대형화·일체화 추세와 달라 발전 방향이 아닙니다.","건립기계의 작업반경과 진행방향을 고려하고 기둥 2본 이상 세울 때 보를 함께 설치한다":"건립기계를 고를 때 작업반경과 진행방향을 보고, 기둥 2본 이상을 세울 때는 보도 함께 답니다.","건조물·중간 제품·소방설비를 진단한다":"건조물, 중간 제품, 소방설비를 진단하는 단계가 정성적 평가입니다.","건축물 각 부위 높이의 기준이며 바라보기 좋고 공사에 지장이 없는 곳에 둔다":"기준점은 건축물 각 부위 높이의 기준이며 바라보기 좋고 공사에 방해되지 않는 곳에 둡니다.","견고·내구적이고 유해물질이 적으며 예각 입형은 좋지 않다":"골재는 견고하고 내구적이며 유해물질이 적어야 하고 모서리가 뾰족한 입형은 좋지 않습니다.","견고하고 재료에 손상·부식이 없으며 발판 간격이 일정해야 한다":"사다리식 통로는 견고하고 손상·부식이 없으며 발판 간격이 일정해야 합니다.","결정요소는 온도·습도·대류(기류)이다":"실효온도의 결정요소는 온도, 습도, 대류(기류)입니다.","경도에 비해 가공성이 좋고 납땜이 가능하며 Cr이 많을수록 내식성이 좋아진다":"스테인리스강은 경도에 비해 가공성이 좋고 납땜이 되며 Cr이 많을수록 내식성이 좋아집니다.","경영관리 개선 자료를 얻고 근로자 심리·욕구를 파악해 불만을 풀고 노동의욕을 높인다":"모랄 서베이로 경영관리 개선 자료를 얻고 근로자 심리·욕구를 알아 불만을 풀어 노동의욕을 높입니다.","경조립 작업은 팔꿈치 높이보다 0~10cm 낮게, 중조립은 10~20cm 낮게 한다":"경조립은 팔꿈치 높이에서 0~10cm 아래에, 중조립은 10~20cm 아래에 작업대를 둡니다.","경험이 부족한 새 기술 공정설비에 실시하려고 개발되었다":"HAZOP은 경험이 부족한 새 기술의 공정설비에 쓰려고 개발되었습니다.","경화 시멘트페이스트 강도 이상이어야 한다":"골재 강도는 굳은 시멘트페이스트의 강도 이상이어야 합니다.","계단과 계단참은 500kgf/m² 이상의 하중에 견뎌야 한다":"계단과 계단참은 500kgf/m² 이상의 하중에도 버티게 만들어야 합니다.","계면에 해당하는 것은 작업공간·표시장치·조종장치이다":"인간-기계 계면에 해당하는 것은 작업공간, 표시장치, 조종장치입니다.","계상기준표 공사종류는 일반건설공사(갑·을)·중건설·철도궤도신설·특수 및 기타건설이다":"일반건설(갑·을)과 중건설, 철도궤도신설, 특수 및 기타건설이 계상기준표의 공사종류 구분입니다.","계수형은 판독오차가 적고 정목동침형은 대략적 편차·변화를 빨리 파악한다":"숫자로 읽는 계수형은 읽는 오차가 작고, 정목동침형은 편차와 변화를 대략 빨리 알아차리게 합니다.","고강도를 만들지만 양생시간이 오래 걸리는 것은 아니다":"오토클레이브 양생은 고강도를 만들면서도 양생시간은 오래 걸리지 않습니다.","고장력 볼트 마찰면·맞닿는 면·현장 용접 부분은 녹막이칠을 하지 않는다":"녹막이칠을 생략하는 곳은 고장력 볼트의 마찰면, 서로 맞닿는 면, 현장 용접 부분입니다.","고장 부위 접근성·징조 검출·부품 교환의 신속성을 고려한다":"보전성 설계는 고장 부위 접근성, 징조 검출, 부품 교환의 신속성을 고려합니다.","고장빈도를 파악해 세우고 명확히 제시한다":"보전방침은 고장빈도를 파악해 세우고 명확하게 제시합니다.","고장원인이 분석되어 더 분석할 필요가 없는 사상이다":"기본사상은 고장원인이 이미 밝혀져 더 분석하지 않아도 되는 사상입니다.","고정·가동·나중매입이며 드리프트 핀은 철골 공사용이다":"앵커볼트 매입에는 고정, 가동, 나중매입 방법이 있고 드리프트 핀은 철골 공사용 공구입니다.","골재는 콘크리트 체적의 약 70~80%를 차지하고 입도는 대소립이 섞인 정도이다":"골재는 콘크리트 부피의 약 70~80%를 차지하며 입도는 큰 알과 작은 알이 섞인 정도를 뜻합니다.","공개경쟁·지명경쟁·수의계약이다":"입찰방식에는 공개경쟁, 지명경쟁, 수의계약이 있습니다.","공기량은 워싱턴 미터, 마모도는 로스앤젤레스 시험기, 분말도는 블레인 장치로 잰다":"공기량 측정에는 워싱턴 미터, 마모도 시험에는 로스앤젤레스 시험기, 분말도 측정에는 블레인 장치를 씁니다.","공기량이 많을수록 슬럼프는 증가하며 공기량은 air-meter로 측정한다":"공기량이 많아지면 슬럼프도 커지고, air-meter 기구로 공기량을 측정합니다.","공사개요서·산업안전보건관리계획서·감전재해예방계획서이다":"건설 유해위험방지계획서에는 공사개요서, 산업안전보건관리계획서, 감전재해예방계획서를 붙입니다.","공사계획 때부터 적정 공법·공기를 택하고 하도급 시 안전관리 책임한계를 명확히 한다":"공사계획 단계에서 적정 공법과 공기를 택하고 하도급은 안전관리 책임한계를 분명히 정합니다.","공칭지름의 7%를 초과하거나 심하게 변형·부식된 것은 쓰지 않는다":"공칭지름의 7%를 넘게 줄었거나 심하게 변형·부식된 와이어로프는 쓰지 않습니다.","관계자 외 출입 방지 조치를 하고 적정 조도를 유지한다":"고소작업대 작업 중에는 관계자 외 출입을 막고 알맞은 조도를 유지합니다.","관리감독자 지휘로 하고 악천후에는 중지하며 로프 지름 감소 기준은 7%이다":"달비계는 관리감독자가 지휘해 조립·해체하고 날씨가 나쁘면 멈추며 로프 지름이 줄어든 정도는 7%가 기준입니다.","관리비 사용계획·건설물 및 기계설비 배치도·재해 시 연락·대피방법이 든다":"안전보건관리계획에는 관리비 사용계획, 건설물 및 기계설비 배치도, 재해 시 연락·대피방법이 듭니다.","관리처방은 권위주의적 리더십·경제적 보상·면밀한 감독과 엄격한 통제이다":"X이론의 관리처방은 면밀한 감독과 엄격한 통제, 권위주의적 리더십, 경제적 보상입니다.","관찰법·면접법·자료분석법·상호평가법이 있다":"평가방법에는 관찰법, 면접법, 자료분석법, 상호평가법이 있습니다.","광명단·워시 프라이머·징크로메이트 도료이고 인광도료는 아니다":"방청도료에는 광명단, 워시 프라이머, 징크로메이트 도료가 있고 인광도료는 아닙니다.","광원을 시선에서 멀리 두고 가깝게 두지 않는다":"눈부심을 줄이려면 광원을 시선에서 멀리 둡니다.","광원의 휘도를 줄이고 가리개·차양·갓을 사용한다":"직사휘광은 광원의 휘도를 줄이고 가리개, 차양, 갓을 써서 처리합니다.","교육(Education)·기술(Engineering)·독려·관리(Enforcement)이다":"시정책은 교육으로 알리고, 기술로 고치고, 독려와 관리로 지키게 하는 세 방향으로 적용합니다.","교육방법은 3요소가 아니다. 평가와 교육기관도 3요소가 아니다":"교육방법과 평가, 교육기관은 교육의 요소에 들지 않습니다.","구덩이파기·줄기초파기·온통기초파기이다":"흙파기 모양에는 구덩이파기, 줄기초파기, 온통기초파기가 있습니다.","구성원에게 자유를 주는 것은 자유방임형이다":"구성원에게 자유를 주고 간섭하지 않는 것은 자유방임형입니다.","구조·건물 규모·부지 위치·기초 구조의 영향을 받는다":"공사기간은 구조와 건물 규모, 부지 위치, 기초 구조에 따라 달라집니다.","구체적이고 이해하기 쉽게 하며 중요도가 높은 항목부터 만든다":"점검표는 구체적이고 이해하기 쉽게 만들고 중요도가 높은 항목부터 적습니다.","구획이 끝날 때까지 계속하고 비빔장소에서 먼 곳부터 시작한다":"구획이 끝날 때까지 이어서 치되 비빔장소에서 먼 곳부터 시작합니다.","굳지 않은 콘크리트의 성질 용어는 워커빌리티·플라스티시티·피니셔빌리티이다":"굳지 않은 콘크리트 성질을 나타내는 용어에는 워커빌리티, 플라스티시티, 피니셔빌리티가 있습니다.","굴착깊이 10.5m 이상 공사가 대상이며 7m·5m 굴착은 아니다":"굴착깊이 10.5m 이상 공사가 대상이며 굴착깊이 7m나 5m는 대상이 아닙니다.","굴착방법·지보공 및 복공·용수처리·환기 조명이 들어간다":"터널 시공계획에는 굴착방법, 지보공 및 복공, 용수처리, 환기·조명이 들어갑니다.","굴착배면 지하수위를 낮추고 웰포인트를 쓰며 차수성이 높은 벽·지수벽으로 투수거리를 길게 한다":"굴착배면 지하수위를 낮추고 지하수를 뽑는 공법을 쓰며 차수성이 높은 벽으로 투수거리를 늘립니다.","굴착 전에 형상·지질·지층 상태, 지하수위, 매설물 유무를 조사한다":"굴착 전 조사 항목은 형상, 지질과 지층, 지하수위, 매설물 유무입니다.","굵은골재 크기가 작아지면 강도가 좋아지고 공기연행제는 시공연도를 좋게 한다":"공기연행제는 시공연도를 높이고, 굵은골재를 작게 하면 강도가 좋아집니다.","권상장치 브레이크·쐐기장치, 본체 연결부 풀림, 권상기 설치상태를 점검한다":"항타기를 조립한 뒤에는 권상기 설치상태와 본체 연결부 풀림, 권상장치 브레이크·쐐기장치를 점검합니다.","균 번식에 적당한 온도는 20~40℃이고 수중에 완전 침수된 목재는 쉽게 부패하지 않는다":"균은 20~40℃에서 잘 번식하고, 물에 완전히 잠긴 목재는 쉽게 썩지 않습니다.","그리스칠을 하고 공장가공 후 운반 전에 1~2회 칠한다":"기계깎기 마무리 면은 그리스칠을 하고 공장가공 뒤 운반 전에 1~2회 칠합니다.","근입심도 확보·상재하중 제거·굴착방법 대체로 방지하며 사질토 지반에서 주로 생기는 것은 아니다":"근입심도 확보, 상재하중 제거, 굴착방법 변경으로 막으며 히빙은 사질토에서 주로 생기지 않습니다.","근접 굴착의 침하·경사를 막거나 침하·경사를 복원할 때 적용하며 인접 지상구조물 철거 때는 아니다":"언더피닝은 근접 굴착의 침하·경사를 막거나 바로잡는 공법이며 인접 구조물 철거 때 쓰는 것은 아닙니다.","금지·경고·지시·안내표지이고 보호표지는 없다":"안전·보건표지는 금지, 경고, 지시, 안내표지로 나뉘며 보호표지라는 종류는 없습니다.","급회전과 작업반경 내 접근을 금하고 고압선 3m 이내 접근을 금한다":"크레인 급회전과 작업반경 안 접근을 막고 고압선 3m 이내 접근을 금합니다.","기경성이며 건조수축이 커서 균열이 생기기 쉽다":"돌로마이트 플라스터는 공기 중에서 굳는 기경성이며 마르며 많이 줄어 균열이 잘 납니다.","기계·기구의 위험성과 작업 순서·동선, 산업보건, 물질안전보건자료이다":"채용 시 교육은 기계·기구의 위험성, 작업 순서와 동선, 산업보건, 물질안전보건자료를 다룹니다.","기계는 예기치 못한 사건을 감지하지 못하나 물리적 힘은 빠르고 지속적으로 적용한다":"예기치 못한 사건은 기계가 감지하지 못하지만, 물리적 힘은 기계가 빠르고 꾸준하게 가합니다.","기계는 융통성이 없고 임기응변을 못하며 과거 경험의 도움을 얻지 못한다":"기계는 융통성이 부족해 상황에 맞게 대처하지 못하고, 지난 경험에서 도움을 얻지도 못합니다.","기계·차량 적재 하중과 가설설비 충격하중":"기계·차량의 적재 하중과 가설설비의 충격하중도 연직하중에 포함됩니다.","기능의 할당과 인간 성능 요건 명세 결정도 기본설계 내용이다":"기본설계 단계에서는 기능을 할당하고 인간이 갖춰야 할 성능 요건을 명세로 정합니다.","기둥 간격 2.5m 이하, 첫 띠장 3.0m 이하이고 강관은 2m 이하이다":"통나무 비계는 기둥을 2.5m 이하로 띄우고 첫 띠장은 3.0m 이하에 두며, 강관은 2m 이하입니다.","기둥은 기초판·연결보·바닥판 위에서 수평으로 이어붓고 아치는 축에 직각으로 한다":"아치는 축에 직각이 되게 이어붓고, 기둥은 기초판·연결보·바닥판 위 수평면에서 이어붓습니다.","기둥 주근은 기초에, 바닥철근은 보·벽체에, 벽 철근은 기둥·보·바닥판에 정착한다":"철근 정착은 기둥 주근이 기초로, 바닥철근이 보·벽체로, 벽 철근이 기둥·보·바닥판으로 들어가게 합니다.","기록성이 없고 검사속도가 빠르며 인체에 위험이 없다":"초음파 탐상법은 기록이 남지 않지만 검사속도가 빠르고 인체에 위험이 없습니다.","기본 두께는 190·150·100mm이다":"속빈 블록의 기본 두께는 190, 150, 100mm입니다.","기술·자본·위험의 부담을 나누고 수급 경쟁을 완화한다":"공동도급은 기술, 자본, 위험을 나누어 부담하고 수급 경쟁을 누그러뜨립니다.","기온 -5℃ 이하에서는 용접하지 않고 슬래그는 제거하며 엔드탭은 절단한다":"기온 -5℃ 이하에서는 용접하지 않으며 슬래그를 떼어 내고 엔드탭은 잘라 냅니다.","기존건물에 근접해 구조물을 구축할 때 언더피닝으로 보강한다":"기존 건물 가까이에 구조물을 지을 때는 언더피닝으로 기초를 보강합니다.","기존 파일머리보다 깊은 구조물을 건설하거나 지하수면 이동으로 지층내력이 약화된 경우에도 쓴다":"기존 파일머리보다 깊게 짓거나 지하수면이 움직여 지층내력이 약해졌을 때도 언더피닝을 합니다.","기준은 25m·30m·15m·20m가 아니다":"풍속 기준은 25m, 30m, 15m, 20m가 아닙니다.","기준은 400kgf/m²이 아니다":"계단과 계단참의 하중 기준은 400kgf/m²가 아닙니다.","기준척도의 신뢰성은 반복성을 뜻한다":"기준척도의 신뢰성은 같은 측정을 되풀이해도 같은 결과가 나오는 반복성을 뜻합니다.","길이가 제조 당시보다 5% 이상 늘었거나 균열이 있으면 쓰지 않는다":"달기체인은 제조 때보다 길이가 5% 이상 늘었거나 금이 가 있으면 쓰지 않습니다.","깊이 10.5m 이상 굴착에는 수위계·경사계·하중 및 침하계를 설치한다":"굴착 깊이가 10.5m 이상이면 수위계, 경사계, 하중계, 침하계로 계측합니다.","나무말뚝은 60cm 이상, 제자리 콘크리트 말뚝은 90cm 이상이다":"말뚝 최소 간격은 나무말뚝이 60cm 이상, 제자리 콘크리트 말뚝이 90cm 이상입니다.","나이테는 춘재부와 추재부가 이루는 동심원 조직이고 심재는 변재보다 강도·내구성이 크다":"심재가 변재보다 강하고 오래가며, 나이테는 춘재부와 추재부가 번갈아 만드는 동심원 조직입니다.","낮에 높고 밤에 낮으며 졸았을 때는 0이다":"긴장 수준은 낮에 높고 밤에 낮으며 졸았을 때는 0입니다.","내관통성·충격흡수성·난연성이고 내구성은 아니다":"안전모 성능시험에는 내관통성, 충격흡수성, 난연성이 있고 내구성은 들지 않습니다.","내습·내열·내한·내유성이 있고 피부에 유해하지 않으며 소독에 견뎌야 한다":"귀마개는 습기·열·추위·기름에 견디고 피부에 해롭지 않으며 소독해도 상하지 않아야 합니다.","높이 10m 이내마다 설치하고 내민길이는 벽면에서 2m 이상이다":"낙하물방지망은 높이 10m 이내마다 설치하고 벽면에서 내민 길이가 2m 이상이어야 합니다.","높이 2m를 초과하면 작업발판 폭을 40cm 이상으로 하며 양측 끝에 올라서서 작업하지 않는다":"말비계 작업발판은 높이 2m 넘으면 폭 40cm 이상이어야 하고 양쪽 끝에 올라서서 일하지 않습니다.","높이 2m 이상 작업발판은 폭 40cm 이상, 발판재료 간 틈 3cm 이하이다":"높이 2m 이상 작업발판은 폭이 40cm 이상이고, 널 사이 틈이 3cm 이하여야 합니다.","높이 8m 이상 비계다리에는 7m 이내마다 계단참을 둔다":"비계다리가 높이 8m 이상이면 7m 안쪽마다 쉴 수 있는 계단참을 만들어야 합니다.","능력부족·정보부족·자기합리화이고 감각차단은 인지과정 착오이다":"판단과정 착오는 능력부족, 정보부족, 자기합리화이고 감각차단은 인지과정 착오입니다.","다경로하중 구조·교대 구조·하중경감 구조·중복구조이다":"Fail-safe 구조에는 다경로하중 구조, 교대 구조, 하중경감 구조, 중복구조가 있습니다.","다량의 사실을 체계적으로 전달하거나 미지 분야를 단기에 습득시키는 데는 맞지 않다":"많은 사실을 체계적으로 전달하거나 모르는 분야를 단기에 익히게 하는 데는 토의식이 맞지 않습니다.","다른 목적에 쓴 금액을 감액하고 미사용 금액의 반환을 요구할 수 있다":"발주자는 다른 목적에 쓴 금액을 감액하고 쓰지 않은 금액의 반환을 요구할 수 있습니다.","다른 시스템 프로그램 영역과 조정하며 분리·배제하지 않는다":"시스템 안전업무는 다른 시스템 프로그램 영역과 조정하며 따로 떼어 배제하지 않습니다.","단열성·차음성·내화성이 크고 현장 절단·가공이 가능하며 흡수율은 크다":"ALC는 단열성, 차음성, 내화성이 크고 현장에서 자르고 가공할 수 있으나 흡수율이 큽니다.","단열재는 비중이 작고 흡수율이 낮으며 열전도율이 낮아야 한다":"단열재는 가볍고 물을 덜 먹으며 열을 잘 전하지 않는 재료여야 합니다.","단위수량과 물시멘트비를 되도록 적게 한다":"수밀콘크리트는 단위수량과 물시멘트비를 되도록 적게 합니다.","단위수량이 늘고 응결이 촉진되며 균열이 생기기 쉽다":"서중콘크리트는 단위수량이 늘고 응결이 빨라지며 균열이 생기기 쉽습니다.","단위수량이 클수록 건조수축이 크고 골재 공극률이 적을수록 팽창·수축이 적다":"골재 공극률이 작으면 팽창·수축이 적고, 단위수량이 클수록 건조수축이 커집니다.","단위수량이 클수록 커지고 골재가 경질이거나 부재가 크면 작아진다":"단위수량이 클수록 건조수축이 커지고 골재가 단단하거나 부재가 크면 작아집니다.","달기섬유로프 가닥이 절단된 것은 쓰지 않고 달비계 작업발판 폭은 40cm 이상이다":"끊어진 가닥이 있는 달기섬유로프는 쓰지 않으며 달비계 작업발판 폭은 40cm 이상으로 합니다.","달기와이어로프·달기강선의 안전계수는 10 이상이다":"안전계수가 10 이상이어야 쓸 수 있는 부재는 달기와이어로프와 달기강선입니다.","달기체인·달기후크는 5 이상, 달기강대는 강재 2.5 이상·목재 5 이상이다":"안전계수 기준은 달기체인·달기후크가 5, 달기강대가 강재 2.5·목재 5 이상입니다.","당면한 사태에 의식의 초점이 합치되지 않으면 대응력이 떨어진다":"의식의 초점이 눈앞의 사태와 맞지 않으면 대응이 늦어집니다.","더운 환경에 적응하면 발한이 시작되고 피부 온도와 피부 혈액량이 늘며 직장 온도는 오르지 않는다":"더위에 적응한 몸은 땀을 내기 시작하고 피부 혈액량이 늘지만 직장 온도는 따라 오르지 않습니다.","도로폭 유지·지반 부동침하 방지·갓길 붕괴 방지로 하며 울·손잡이는 아니다":"도로폭 유지, 지반 부동침하 방지, 갓길 붕괴 방지가 전도·전락 방지 조치이고 울·손잡이는 아닙니다.","도면의 도해적 표현과 입찰참가 자격 평가기준은 시방서 기재사항이 아니다":"도면으로 표현하는 도해와 입찰참가 자격 평가기준은 시방서에 적을 내용이 아닙니다.","도표는 정적 표시장치이고 온도계·속도계는 동적이며 산소소비량은 더글라스백으로 잰다":"산소소비량은 더글라스백으로 재며, 표시장치 중 도표는 정적이고 온도계와 속도계는 동적입니다.","독립·줄기초·복합기초이고 직접기초는 이 분류가 아니다":"기초판 형식은 독립, 줄기초, 복합기초로 나누며 직접기초는 지정 형식 분류에 속합니다.","동결 골재나 눈·얼음이 섞인 골재는 쓰지 않고 AE제·AE감수제를 쓴다":"얼어붙은 골재나 눈·얼음이 섞인 골재는 피하고, AE제나 AE감수제를 씁니다.","동결융해 저항·내약품성이 크고 용적변화와 백화가 적다":"오토클레이브 제품은 동결융해 저항과 내약품성이 크고 용적변화와 백화가 적습니다.","동기·기질·감정·습성·습관이다":"산업심리의 다섯 요소는 동기, 기질, 감정, 습성, 습관입니다.","두께·밀도·표면상태이고 강도는 아니다":"단열성에 영향을 주는 요인은 두께, 밀도, 표면상태이고 강도는 아닙니다.","드래그라인과 리버스 서큘레이션 드릴":"드래그라인과 리버스 서큘레이션 드릴은 굴착 장비라 철골 세우기 장비가 아닙니다.","디젤햄머는 피어기초와 관계 없다":"디젤햄머는 말뚝을 박는 기계라 피어기초와 관계가 없습니다.","띠장방향 1.5~1.8m, 장선방향 1.5m 이하이다":"비계 기둥은 띠장 방향으로는 1.5~1.8m 간격, 장선 방향으로는 1.5m 이하 간격으로 세웁니다.","라인 관리자에 의한 안전보건 추진이 라인화이다":"라인화는 라인 관리자가 안전보건을 추진하는 것입니다.","라인형·스태프형·라인스태프형이다":"안전관리 조직에는 라인형, 스태프형, 라인스태프형이 있습니다.","레미콘 차에 유도자를 두고 플렉시블 호스를 반경 1m 이하로 구부리지 않는다":"펌프카 작업에서 레미콘 차를 유도할 사람을 세우고, 플렉시블 호스는 반경 1m 이하로 꺾지 않습니다.","리벳은 엇모배치가 많이 쓰이고 옆남기 1.5d·끝남기 2.0d 이상이다":"리벳은 엇모로 배치하는 경우가 많고 옆남기는 1.5d 이상, 끝남기는 2.0d 이상 둡니다.","리프트·압력용기·곤돌라이고 선반은 아니다":"안전검사 대상은 리프트, 압력용기, 곤돌라이고 선반은 해당하지 않습니다.","마모 저항이 커지고 알칼리 골재반응을 촉진한다":"염화칼슘을 섞으면 표면 마모 저항이 커지는 대신 알칼리 골재반응이 빨라집니다.","막대형·거푸집·표면 진동기이며 내부 진동기를 원칙으로 한다":"진동다짐기는 막대형, 거푸집, 표면 진동기가 있으며 내부 진동기를 원칙으로 합니다.","막장구간 60lux, 터널 중간구간 50lux, 수직구구간 30lux 이상이다":"막장구간은 60lux, 터널 중간은 50lux, 수직구는 30lux가 최소 조도입니다.","만족도를 얻는 수단이 아니다":"작업분석은 작업 만족도를 얻는 수단이 아닙니다.","말뚝 중심 간격은 마구리 지름의 2.5배 이상이다":"말뚝을 박을 때 중심 사이 거리는 마구리 지름의 2.5배 이상 벌려야 합니다.","망입유리는 깨져도 파편이 튀지 않고 복층유리는 방음·열차단이 우수하다":"복층유리는 방음과 열차단에 뛰어나고, 망입유리는 깨져도 파편이 흩어지지 않게 합니다.","머리받침끈·머리고정대·머리받침고리로 구성된다":"착장체는 머리받침끈, 머리고정대, 머리받침고리로 이루어집니다.","메시지가 단순하고 그때의 사건을 다루면 좋다":"청각 표시는 메시지가 단순하고 그 순간의 사건을 다룰 때 알맞습니다.","메탈터치 부위는 페이싱머신, 형강 절단은 해크소, 판재 절단은 플레이트 쉐어링기로 한다":"형강은 해크소, 판재는 플레이트 쉐어링기로 자르고, 메탈터치로 맞닿을 부위는 페이싱머신으로 깎습니다.","모래는 진흙보다 투수계수가 크고 모래에서는 유효입경의 제곱에 비례한다":"모래는 진흙보다 물이 잘 통하며 모래의 투수계수는 유효입경을 제곱한 값에 비례합니다.","목구조에서 띠쇠는 인장부 접합 보강철물로 볼트와 함께 쓴다":"띠쇠는 목구조에서 인장부 접합을 보강하는 철물이며 볼트와 함께 씁니다.","목시거리가 길수록 조절 정확도가 떨어진다":"눈으로 보는 거리인 목시거리가 길어지면 미세 조절이 부정확해집니다.","목재 난간은 5cm² 이상 단면이어야 하며, 계단참의 높이를 3.5m 초과 금지로 정하지는 않는다":"계단참 높이를 3.5m 초과 금지로 정하지 않으며 목재 난간 단면은 5cm² 이상이어야 합니다.","목재·아스팔트·플라스틱이고 시멘트는 무기재료이다":"목재, 아스팔트, 플라스틱은 유기재료이고 시멘트는 무기재료입니다.","못·나사 부착력은 감소하지 않으며 옹이·수지낭 제거는 목적이 아니다":"목재 건조의 목적에 옹이·수지낭 제거는 없고 건조해도 못·나사 부착력은 줄지 않습니다.","몽둥달고나 떨공이로 하고 견고한 자갈층에는 하지 않는다":"견고한 자갈층에는 다지지 않고, 잡석은 몽둥달고나 떨공이로 내리쳐 다집니다.","무(無)의 원칙·참가의 원칙·선취의 원칙이다":"무(無)의 원칙, 참가의 원칙, 선취의 원칙을 무재해운동의 원칙이라 부릅니다.","물시멘트비가 증가하면 강도가 저하되고 수량이 크면 건조수축이 커진다":"물시멘트비가 늘면 강도가 낮아지고 물이 많으면 건조수축도 커집니다.","물시멘트비가 커지면 강도는 작아지며 결정요인은 내구성·수밀성·압축강도이다":"물시멘트비가 커지면 강도가 작아지며 이를 정하는 요인은 내구성, 수밀성, 압축강도입니다.","물시멘트비가 크면 강도가 감소하고 블리딩이 증가하며 작을수록 작업능률이 떨어진다":"물시멘트비가 크면 강도가 떨어지고 블리딩이 늘며, 너무 작으면 작업이 어려워집니다.","물시멘트비가 클수록, 컨시스턴시가 클수록 블리딩과 침하가 크다":"물이 많고 반죽이 묽을수록 블리딩과 침하가 커집니다.","물체나 표면에 도달하는 광의 밀도이다":"조도는 물체나 표면에 도달하는 빛의 밀도입니다.","묽은 콘크리트일수록, 단면이 클수록 측압이 크다":"묽은 콘크리트와 큰 단면일수록 측압이 큽니다.","밑으로부터 동의에 의해 권한을 부여받고 개인 능력이 권한의 근거이다":"리더십은 아래로부터 동의를 받아 권한이 생기고 개인 능력이 권한의 근거입니다.","바닥철근 최대간격은 주근 20cm 이하, 배력근 30cm 이하이다":"바닥철근 간격은 주근이 20cm, 배력근이 30cm를 넘지 않는 선까지 허용됩니다.","바닥판·보 밑 거푸집에는 굳지 않은 콘크리트 중량을 고려한다":"바닥판과 보 밑 거푸집은 굳지 않은 콘크리트의 중량을 설계에 고려합니다.","바퀴에는 브레이크·쐐기 등 제동장치를 하고 생략하지 않으며 작업발판 최대적재하중은 250kg 이하이다":"작업발판 최대적재하중은 250kg 이하이며 바퀴에는 브레이크·쐐기 같은 제동장치를 반드시 답니다.","바탕작업이 단순하고 양생이 짧은 공법이 아니다":"미장공법은 바탕작업이 번거롭고 양생이 길어 단순하고 짧은 공법이 아닙니다.","반사율 80% 이상이고 작업영역에 따른 휘도 차이는 작게 한다":"천장은 반사율을 80% 이상으로 하고 작업영역에 따른 휘도 차이는 작게 둡니다.","반사율이 커서 열차단재로 쓰이고 연질이라 손상되기 쉬우며 내화성이 적다":"알루미늄은 반사율이 커서 열차단재로 쓰이고 연해 손상되기 쉬우며 내화성이 낮습니다.","반응기·교반기·추출기 사용·세척 작업과 탱크 내 작업도 대상이다":"반응기·교반기·추출기를 쓰거나 씻는 작업, 탱크 안 작업에도 특별교육을 해야 합니다.","발파 안전담당자는 대피장소·경로를 지시하고 대피 확인과 불발장약 점검을 한다":"불발장약 점검과 대피 확인은 발파 안전담당자가 하고, 대피장소와 경로도 그가 알려 줍니다.","발판을 겹쳐 이음할 때는 장선 위에서 20cm 이상 겹치며 돌출된 못·옹이가 없어야 한다":"발판을 겹쳐 이을 때는 장선 위에서 20cm 이상 겹치고 못이나 옹이가 튀어나오지 않아야 합니다.","방망에는 신품 강도·제조자명·그물코를 표시하고 망사 직경은 표시사항이 아니다":"방망에 표시할 사항은 신품 강도, 제조자명, 그물코이고 망사 직경은 표시하지 않습니다.","방심과 공상·개성적 결함·판단력 부족이며 인간성능과 압박은 선형관계가 아니다":"인간성능과 압박이 선형관계가 아니라는 점과 함께 방심·공상, 개성적 결함, 판단력 부족이 정신적 요소입니다.","방치하지 않고 기초·본체를 마무리하며 대피통로를 확보하고 수평 연속 시공은 하지 않는다":"굴착 구간은 그대로 두지 말고 기초와 본체를 마무리하며 대피통로를 확보하되 수평으로 연속 시공하지는 않습니다.","방호선반·낙하물방지망·출입금지구역·보호구로 막는다":"물체 낙하·비래는 방호선반, 낙하물방지망, 출입금지구역, 보호구로 막습니다.","방화는 플라스터 피복·방화페인트·인산암모늄 도포로 하고 PCP는 유용성 방부제이다":"PCP는 유용성 방부제이고, 방화에는 플라스터 피복, 방화페인트, 인산암모늄 도포를 씁니다.","배토공·배수공·압성토공이며 절토 높이를 늘리면 안 된다":"배토공, 배수공, 압성토공으로 막으며 절토 높이를 늘리면 오히려 위험합니다.","배합강도는 설계기준강도보다 커야 하고 수밀콘크리트는 물결합재비 50% 이하이다":"수밀콘크리트는 물결합재비가 50% 이하여야 하고, 배합강도는 설계기준강도를 웃돌아야 합니다.","백호는 지반보다 낮은 곳을, 클램쉘은 수직·수중을 굴삭한다":"백호는 자기 위치보다 낮은 곳을 파고, 클램쉘은 수직으로 깊이 파거나 물속을 팝니다.","밸런스 웨이트·지브·마스트이고 에이프런은 아니다":"타워크레인은 밸런스 웨이트, 지브, 마스트로 이루어지며 에이프런은 구성품이 아닙니다.","버팀줄만으로 안정시킬 때는 3개 이상을 같은 간격으로 하고 연약지반에는 깔판을 쓴다":"버팀줄만으로 세울 때는 같은 간격으로 3개 이상 쓰고, 연약지반이면 깔판을 받칩니다.","벤치마크 설치·지하매설물 조사·지질과 지하수 조사이며 그라운드 라인은 착수 때 정하지 않는다":"대지 확인은 벤치마크 설치와 지하매설물, 지질·지하수 조사이고 그라운드 라인은 착수 때 정하지 않습니다.","벼락 우려 시 장전 작업을 중지하고 얼어붙은 다이나마이트는 고열물에 직접 접촉시키지 않는다":"벼락이 칠 것 같으면 장전을 멈추고, 얼어붙은 다이나마이트를 고열물에 직접 대지 않습니다.","변색·부패와 균류 발생을 막고 방부제·도료·접착제 효과를 높인다":"목재 건조는 변색·부패와 균류를 막고 방부제·도료·접착제 효과를 높입니다.","변재는 심재보다 건조 시 용적변화가 크고 섬유방향 인장강도가 압축강도보다 크다":"변재는 심재보다 마를 때 부피가 더 크게 변하고 섬유방향 인장강도가 압축강도보다 큽니다.","변재는 심재보다 수축이 크고 건조는 섬유포화점 이하부터 수축한다":"변재는 심재보다 더 많이 수축하고, 섬유포화점 아래로 건조될 때부터 수축이 일어납니다.","병렬계 수명은 요소 중 가장 긴 것으로 정해진다":"병렬계의 수명은 구성 요소 가운데 가장 오래가는 것으로 정해집니다.","병리적·신체적·사회심리적 요인이고 생물학적 요인은 아니다":"재해의 심리학적 요소는 병리적, 신체적, 사회심리적 요인이고 생물학적 요인은 아닙니다.","보류(retention)·위험감축·전가·회피 등이다":"위험조정 기술에는 보류(retention), 위험감축, 전가, 회피 등이 있습니다.","보상세력·합법세력·전문세력이 있다":"리더의 세력 유형에는 보상세력, 합법세력, 전문세력이 있습니다.","보상적·강압적·합법적 권한이다":"조직이 부여하는 권한은 보상적, 강압적, 합법적 권한입니다.","보수·작업조건·관리감독·복지제도이다":"위생요인은 보수, 작업조건, 관리감독, 복지제도입니다.","보일링과 좌굴은 옹벽 안정조건 검토 사항이 아니다":"옹벽 안정조건에는 보일링과 좌굴 검토가 들어 있지 않습니다.","보일링은 사질지반에서 지반수위와 터파기 저면의 수위차로 생기며 근입깊이를 깊게 한다":"수위차가 사질지반에 터파기 저면으로 물을 밀어 올리면 보일링이 되므로 근입깊이를 깊게 합니다.","보통콘크리트보다 블리딩·침하가 적고 점성이 늘어 분리가 줄어든다":"AE 콘크리트는 점성이 늘어 분리가 줄고 블리딩·침하도 보통콘크리트보다 적습니다.","보통 포틀랜드는 석회석이 주원료, 알루미나 시멘트는 보크사이트와 석회석이 원료이다":"석회석은 보통 포틀랜드의 주원료이고, 알루미나 시멘트는 거기에 보크사이트를 더해 만듭니다.","보호구는 방호성능이 충분하고 품질·외관이 좋고 착용이 간편해야 한다":"방호성능이 충분한 보호구가 좋고, 품질이 괜찮고 쓰기 편해야 현장에서 잘 착용합니다.","보호구·안전인증대상 기계 구입 시 적격품 선정과 안전보건관리규정에서 정한 업무도 한다":"보호구와 안전인증대상 기계는 적격품을 골라 사고, 안전보건관리규정에 적힌 업무도 맡습니다.","보호절연·안전전압 기기·보호접지이다":"간접접촉 방지는 보호절연, 안전전압 기기, 보호접지로 합니다.","부배합 시멘트의 건조수축 균열을 막기 위해 넣는다":"돌가루는 시멘트를 많이 쓴 부배합에서 건조수축 균열이 나지 않게 넣습니다.","부배합이 빈배합보다, 공기량이 많을수록 워커빌리티가 좋고 비빔온도가 높으면 저하된다":"비빔온도가 높으면 워커빌리티가 떨어지고, 반죽이 진한 부배합과 공기량 많은 콘크리트는 워커빌리티가 좋습니다.","부분적으로 녹이 나면 즉시 제거하고 큰 변형을 준 것은 풀림해서 쓴다":"녹이 조금 나면 곧바로 벗기고, 크게 변형시킨 금속은 풀림으로 되돌려 씁니다.","부식성 물질·화기가 없고 직사광선이 닿지 않는 곳에 보관한다":"안전대는 직사광선이 닿지 않고 부식성 물질이나 불씨가 없는 곳에 두고 보관합니다.","부재 경량화·설치 단순화 방향으로 발전한다":"거푸집 공법은 부재를 가볍게 하고 설치를 단순하게 하는 방향으로 발전합니다.","부재를 달아 올린 채 운전대를 이탈하지 않고 달아 올린 채 주행하지 않는다":"운전자는 부재를 달아 올린 채 운전대를 떠나지 않고 달아 올린 채 주행하지 않습니다.","부재 변질을 막고 번호를 식별하기 쉽게 하며 받침대를 두고 벽 부재는 수평으로 포개지 않는다":"야적 부재는 변질되지 않게 받침대를 두고 번호를 붙여 두며, 벽 부재는 수평으로 포개지 않습니다.","부재의 손상·변형·부식·변위·탈락 유무와 접속부·부착부·교차부 상태도 점검한다":"접속부·부착부·교차부 상태와 부재의 손상·변형·부식·변위·탈락도 정기점검 대상입니다.","부품을 빠뜨리고 조립한 것은 생략 오류이다":"부품을 빠뜨리고 조립한 것은 해야 할 일을 하지 않은 생략 오류입니다.","부품 재료는 나일론·폴리에스테르·비닐론이다":"안전대 부품 재료로는 나일론, 폴리에스테르, 비닐론을 씁니다.","부하와의 사회적 간격이 넓은 것은 헤드십이다":"부하와의 사회적 간격이 넓은 것은 리더십이 아니라 헤드십의 특징입니다.","분당 5kcal 작업도 휴식이 필요하며 기초대사량은 의자에 앉아 재지 않는다":"기초대사량은 의자에 앉은 채 재지 않고, 분당 5kcal 작업도 쉬어 가며 해야 합니다.","분말도가 높으면 조기강도가 커지고 수화작용이 촉진되며 초기균열이 생긴다":"분말도가 높으면 수화가 빨라 조기강도가 커지지만 초기균열이 생기기 쉽습니다.","불규칙하며 고장률이 시간에 관계없이 일정하고 사후보전이 적당하다":"우발고장은 불규칙하게 일어나고 고장률이 시간과 관계없이 일정하며 사후보전이 알맞습니다.","불도저·그레이더·스크레이퍼이다":"지반을 고르는 장비에는 불도저, 그레이더, 스크레이퍼가 있습니다.","불안전한 행동 또는 불안전한 상태이다":"불안전한 행동이나 불안전한 상태가 사고 연쇄의 세 번째 단계입니다.","붐·암·버킷이고 블레이드는 아니다":"굴착기 전부장치는 붐, 암, 버킷으로 이루어지고 블레이드는 불도저 부품입니다.","블론 아스팔트는 스트레이트보다 연화점이 높고 내구력이 크다":"연화점이 더 높고 오래 견디는 쪽은 스트레이트가 아니라 블론 아스팔트입니다.","블리딩으로 떠오른 미립물이 침적된 것이며 단위수량이 적으면 블리딩이 줄어든다":"레이턴스는 블리딩으로 떠오른 미립물이 가라앉아 굳은 것이며 단위수량이 적으면 블리딩이 줄어듭니다.","비율은 1:29:270이나 1:10:30이 아니다":"하인리히 재해구성비율은 1:29:270이며 1:10:30이 아닙니다.","비중 약 2.7, 융점 약 660℃이며 철보다 융점이 낮다":"알루미늄은 비중이 약 2.7이고 융점이 약 660℃로 철보다 융점이 낮습니다.","빗물·지하수를 배제하고 지반은 안전한 경사로 하며 안전난간은 낙하 대책이 아니다":"붕괴 방지는 빗물과 지하수를 빼내고 지반을 안전한 경사로 하며 안전난간은 낙하 대책이 아닙니다.","뾰족한 것을 쓰고 눈금면에 밀착시킨다":"지침은 뾰족한 모양을 쓰고 눈금면에 가까이 붙입니다.","뿜칠은 큰 면적을 단시간에 시공하고 성형판은 주로 기둥·보에 쓰며 타설은 임의 형상이 가능하다":"큰 면적은 뿜칠로 짧은 시간에 시공하고, 성형판은 기둥·보에, 타설은 임의 형상에 적합합니다.","사건 확률의 역수에 로그(밑 2)를 취해 구한다":"정보량은 사건 확률의 역수에 밑이 2인 로그를 취해 구합니다.","사고로 인한 손실이 우연에 의해 결정된다는 원칙이다":"손실 우연의 원칙은 같은 원인의 사고라도 손실 크기는 우연히 정해진다는 뜻입니다.","사고방지 기본원리는 원인계기·손실우연·예방가능의 원칙이다":"원인계기, 손실우연, 예방가능의 세 원칙이 사고방지의 기본원리입니다.","사고빈도·인간성능척도·생리학적 지표·주관적 반응이다":"인간기준 네 가지 유형은 사고빈도, 인간성능척도, 생리학적 지표, 주관적 반응입니다.","사고원인 정량화·체크리스트 작성·신뢰성 분석이며 연역적 해석 기법이다":"FTA의 기대효과는 사고원인 정량화, 체크리스트 작성, 신뢰성 분석이며 연역적으로 해석합니다.","사고·표현력, 민주적 태도, 타인 의견 존중을 기를 수 있다":"토의식은 사고력과 표현력, 민주적 태도, 남의 의견을 존중하는 태도를 길러 줍니다.","사람 접근에 주의하고 스윙 전 주위를 살피며 고압선과 안전간격을 둔다":"셔블계 장비는 사람이 다가오지 못하게 하고 스윙 전 주위를 둘러보며 고압선과 거리를 둡니다.","사면 경사·단위체적 중량·내부마찰각과 관계되고 입도는 아니다":"사면 안정성은 사면 경사, 단위체적 중량, 내부마찰각과 관련되고 입도와는 직접 관련되지 않습니다.","사용은 신뢰도 개선 방법이 아니다":"고가 재료를 쓰는 것은 신뢰도를 개선하는 방법이 아닙니다.","산소농도를 측정하고 오르내리는 승강설비를 설치한다":"잠함 내부를 굴착할 때는 산소농도를 측정하고 오르내리는 승강설비를 설치합니다.","산·알칼리·해수에 약하고 동보다 전기전도성이 작으며 열팽창이 크다":"알루미늄은 열팽창이 크고 동보다 전기가 덜 통하며 산·알칼리·해수에는 쉽게 부식됩니다.","산업안전·사고예방, 건강증진·질병예방, 유해·위험 작업환경 관리이다":"근로자 정기교육은 산업안전과 사고예방, 건강증진과 질병예방, 작업환경 관리를 다룹니다.","산업용 로봇·인쇄기·혼합기이다":"자율안전확인 대상은 산업용 로봇, 인쇄기, 혼합기입니다.","상부난간대는 바닥면에서 90~120cm, 발끝막이판은 10cm 이상 높이이다":"난간 높이는 바닥에서 90~120cm가 상부난간대 자리이고, 발끝막이판은 10cm를 넘겨 세웁니다.","상부난간대·중간난간대·발끝막이판·난간기둥으로 구성된다":"안전난간은 상부난간대, 중간난간대, 발끝막이판, 난간기둥으로 구성됩니다.","상완을 자연스럽게 늘어뜨린 채 전완으로 닿는 영역이며 손목만 움직이는 영역이 아니다":"정상작업영역은 상완을 자연스럽게 내리고 전완만으로 닿는 범위이며 손목만 움직이는 범위는 아닙니다.","상하수도관·가스·송유관·전기·전화 케이블이다":"지하 매설물에는 상하수도관, 가스, 송유관, 전기와 전화 케이블이 있습니다.","색깔·사용방법·다각능률은 배치 원칙이 아니다":"배치 원칙에 색깔, 사용방법, 다각능률은 들지 않습니다.","색채조절이 부적합하면 안전표지가 거슬리고 식별이 어려우며 무채색은 중압감을 준다":"색채조절이 맞지 않으면 안전표지가 눈에 거슬리고 구분이 어려워지며 무채색은 압박감을 줍니다.","샌드드레인·웰포인트·페이퍼드레인이며 약액주입은 아니다":"탈수공법에는 샌드드레인, 지하수를 뽑는 공법, 페이퍼드레인이 있고 약액주입은 아닙니다.","샘플러를 30cm 관입시키는 타격 횟수이며 연약 점토 조사용은 아니다":"N값은 샘플러를 30cm 박는 데 드는 타격 횟수이며 연약 점토를 조사하는 용도는 아닙니다.","생리학적·반응·육안 모니터링이고 환경 모니터링은 아니다":"정신부하의 직접 방법은 생리학적, 반응, 육안 모니터링이고 환경 모니터링은 아닙니다.","생산손실과 통신급여는 직접비가 아니다":"통신급여와 생산손실은 직접비로 보지 않습니다.","석재는 비중이 클수록 강도가 크고 흡수율이 클수록 강도가 낮다":"석재는 비중이 클수록 치밀해 단단하고, 물을 많이 먹을수록 강도가 낮아집니다.","설계 강도 이상의 급격한 스트레스로 생기는 고장은 우발고장이다":"설계 강도를 넘는 급격한 스트레스가 갑자기 걸려 일어나는 고장이 우발고장입니다.","설계기준강도의 2/3 이상일 때 해체한다":"바닥슬래브 밑 거푸집은 설계기준강도의 3분의 2 이상일 때 해체합니다.","설비 결함·불안전 상태를 제거해 안전성을 확보하고 성능을 유지하는 것이다":"안전점검은 설비의 결함과 불안전 상태를 없애 안전성을 확보하고 성능을 유지하려는 것입니다.","설비고장 정지시간÷설비가동시간이다":"설비고장 강도율은 설비고장 정지시간을 설비가동시간으로 나눈 값입니다.","설비이력카드·MTBF 분석표·고장원인대책표이다":"보전기록 자료에는 설비이력카드, MTBF 분석표, 고장원인대책표가 있습니다.","설비 전체보다 단위별·부문별로 나누어 검토하고 위험이 예상되는 부문에 상세히 한다":"HAZOP은 설비를 한꺼번에 보지 않고 단위별·부문별로 쪼개 위험이 예상되는 곳을 상세히 검토합니다.","설치방법 불량·연약지반 무보강·규정 이상 중량물 적재이다":"크레인 도괴는 설치방법 불량, 연약지반 무보강, 규정 이상 중량물 적재로 일어납니다.","설치·수리·점검·해체는 순간풍속 초당 10m를 초과하면 중지한다":"타워크레인 설치·수리·점검·해체는 순간풍속 초당 10m를 넘으면 중지합니다.","섬유포화점은 함수율 약 30%이며 기건재 함수율은 약 15%이다":"섬유포화점은 함수율 약 30%이고, 공기 중에서 마른 기건재 함수율은 약 15%입니다.","성능 향상·인력 이용률 향상·생산 및 보전 경제성 증대이다":"인간공학의 가치는 성능 향상, 인력 이용률 향상, 생산 및 보전의 경제성 증대입니다.","성형판 붙임·뿜칠·미장·타설공법이다":"철골 내화피복 공법에는 성형판 붙임, 뿜칠, 미장, 타설공법이 있습니다.","세미 실드 공법은 흙막이 공법이 아니고 비탈면 개굴착도 흙막이벽 개굴착이 아니다":"흙막이 공법에는 세미 실드 공법이 없으며, 비탈면 개굴착 역시 흙막이벽 개굴착과 다릅니다.","세우기 계획 때 공장과 반입 시간·부재수·반입 순서를 협의한다":"철골 세우기 계획을 짤 때 공장과 반입 시간, 부재수, 반입 순서를 맞춰 둡니다.","소석고가 주성분이며 결정수를 방출해 내화성이 있고 경화가 빠르다":"석고 플라스터는 소석고가 주성분이라 굳을 때 결정수를 내보내 불에 강하고 빨리 굳습니다.","소성한계·3축압축·비중시험이고 할렬인장시험은 아니다":"소성한계, 3축압축, 비중시험은 토질시험이고 할렬인장시험은 콘크리트 시험이라 해당하지 않습니다.","소음원 통제·격리, 차폐장치 사용, 소음수준 감소, 보호구 착용이다":"소음원을 통제하거나 격리하고 차폐장치와 보호구를 쓰며 소음수준을 낮추는 것이 소음 대책입니다.","소음은 양쪽 귀에, 신호는 한쪽 귀에 들리게 한다":"소음은 양쪽 귀로, 신호는 한쪽 귀로만 들려주어 구분이 쉽게 합니다.","소음의 반사나 연속 소음 노출은 대책이 아니다":"소음을 반사하거나 소음에 계속 노출되는 것은 대책이라 할 수 없습니다.","소음이 심할 때 통화이해도를 높이며 주변 음을 완벽히 차단하지 않는다":"귀마개는 주변 소리를 완전히 막지는 않아서 소음이 클 때 말소리 이해도를 높여 줍니다.","소질적 조건에 교육, 작업환경 불량에 작업순서 정비를 대응시키지 않는다":"소질적 조건에 교육을, 작업환경 불량에 작업순서 정비를 짝짓는 것은 맞지 않습니다.","소화설비·정지신호·유해행위 금지에 쓰고 위험경고는 빨강이 아니다":"빨강은 소화설비, 정지신호, 유해행위 금지에 쓰고 위험경고에는 빨강을 쓰지 않습니다.","손익을 공동 계산해 위험을 분산하며 특정 공사에 한정되는 일시적 방식이다":"공동도급은 손익을 함께 계산해 위험을 나누고 특정 공사에만 한시적으로 맺는 방식입니다.","수공구는 사용할 때 무게 균형이 유지되도록 설계한다":"수공구는 쓰는 동안 무게 균형이 유지되게 설계합니다.","수공구 크기에 맞추는 것은 원칙이 아니다":"손잡이를 수공구 크기에 맞춰야 한다는 말은 설계 원칙에 들지 않습니다.","수령이 늘면 변재가 심재로 변하며 섬유 평행 방향에서 인장강도가 압축강도보다 크다":"나무가 오래 자라면 변재가 심재로 바뀌고, 섬유와 나란한 방향에서는 인장강도가 압축강도보다 큽니다.","수리적으로 정성·정량, 논리적으로 귀납·연역으로 나뉜다":"분석은 수리적으로는 정성과 정량, 논리적으로는 귀납과 연역으로 갈립니다.","수밀성·워커빌리티를 좋게 하고 저알칼리시멘트 효과를 낸다":"플라이애시는 수밀성과 워커빌리티를 높이고 저알칼리시멘트와 같은 효과를 냅니다.","수밀성이 적어 지하수가 많은 곳에 부적당하다":"목재 널말뚝은 물이 새기 쉬워 지하수가 많은 곳에는 알맞지 않습니다.","수산화석회가 탄산가스와 반응해 탄산석회가 되는 현상이다":"중성화는 수산화석회가 탄산가스와 만나 탄산석회로 바뀌는 현상입니다.","수용성 아크릴 수지와 천연골재가 주원료이고 단열성·부착성이 좋다":"드라이비트용 도료는 수용성 아크릴 수지와 천연골재가 주원료이고 단열성과 부착성이 좋습니다.","수위저하·샌드드레인·성토 공법은 강제압밀 공법이다":"수위저하, 샌드드레인, 성토 공법은 물을 짜내 굳히는 강제압밀 공법입니다.","수직 5m·수평 5m 이내마다 하고 틀비계는 수평 8m 이내이다":"벽 연결은 수직 5m, 수평 5m 이내마다 하며 틀비계는 수평 8m 이내입니다.","수축에 의한 손상을 막고 강도·열전도성이 개선된다":"건조하면 수축으로 인한 손상을 막고 강도와 열전도성이 좋아집니다.","수축이 작아 큰 단면공사에 유리하고 긴급·동절기 공사용이 아니다":"큰 단면 공사에는 수축이 작은 중용열 시멘트가 맞고, 급하게 굳혀야 하는 긴급·동절기 공사에는 맞지 않습니다.","수평면과의 각도는 20~30도를 유지한다":"낙하물방지망과 수평면이 이루는 각도는 20~30도를 유지합니다.","수화열이 적어 매스콘크리트에 쓰고 내해수성이 크며 초기강도는 낮다":"고로 시멘트는 열이 덜 나서 매스콘크리트에 알맞고 바닷물에 강하지만 초기에는 강도가 낮습니다.","순간풍속이 초당 35m를 초과하면 붕괴 방지 조치를 한다":"건설작업용 리프트는 순간풍속이 초당 35m를 넘으면 붕괴 방지 조치를 합니다.","스위치를 위로, 버튼을 우측으로, 조종장치를 앞으로 미는 것이다":"켤 때 기대하는 운동방향은 스위치를 위로, 버튼을 오른쪽으로, 조종장치를 앞으로 미는 것입니다.","스크레이퍼는 굴착과 상차 운반을 하며 가이데릭은 토공사용이 아니다":"스크레이퍼는 파고 싣고 나르는 일까지 하며, 가이데릭은 토공사용이 아닙니다.","스팬 중앙 또는 단부 1/4 부분에서 이어치며 응력이 적은 곳이 좋다":"슬래브와 보는 스팬 중앙이나 단부 1/4 부분에서 이어치며 응력이 적은 곳이 좋습니다.","스페이서는 철근이 거푸집에 밀착되는 것을 방지하며 폼타이는 측압으로 벌어지는 것을 막는다":"스페이서는 철근이 거푸집에 붙지 않게 하고, 폼타이는 측압으로 거푸집이 벌어지는 것을 막습니다.","슬럼프 15cm 이하, 단위시멘트량 최소 300kg/m³, 물시멘트비 60% 이하이다":"프리캐스트 콘크리트 배합은 슬럼프 15cm 이하, 단위시멘트량 300kg/m³ 이상, 물시멘트비 60% 이하입니다.","슬럼프 180mm 이하, 물시멘트비 최대 60%이다":"경량골재 콘크리트는 슬럼프 180mm 이하, 물시멘트비 최대 60%로 합니다.","슬럼프가 늘고 재료분리·블리딩이 줄지만 공기량이 늘면 압축강도는 낮아진다":"AE 콘크리트는 슬럼프가 커지고 재료분리와 블리딩이 줄지만 공기량이 늘면 압축강도는 낮아집니다.","슬럼프 로스가 발생하고 초기강도가 빠르다고 장기강도가 높지는 않다":"서중콘크리트는 슬럼프 로스가 생기며 초기강도가 빨라도 장기강도가 높아지지는 않습니다.","슬럼프·블리딩·공기량이고 블레인은 시멘트 시험이다":"묽은 콘크리트 시험은 슬럼프, 블리딩, 공기량이고 블레인은 시멘트 시험입니다.","슬럼프·플로우·리몰딩 시험이고 슈미트해머는 경화 콘크리트용이다":"굳지 않은 콘크리트는 슬럼프, 플로우, 리몰딩 시험으로 재고 슈미트해머는 굳은 콘크리트에 씁니다.","습기에 약하나 곡면가공이 쉽고 가공성·접착성이 좋으며 경량은 아니다":"MDF는 습기에 약하지만 곡면가공이 쉽고 가공성과 접착성이 좋으며 가볍지는 않습니다.","습기·탄산가스와 반응해 녹슬고 Zn·Sn·Ni 도금으로 방식한다":"철강은 습기와 탄산가스와 반응해 녹슬며 Zn, Sn, Ni 도금으로 방식합니다.","습숙도는 평가도구 기준이 아니고 실연법은 평가방법 종류가 아니다":"평가도구의 기준에 습숙도는 없고 평가방법 목록에도 실연법은 없습니다.","습윤양생·증기양생·오토클레이브양생이고 건조양생은 아니다":"양생방법에는 습윤양생, 증기양생, 오토클레이브양생이 있고 건조양생은 아닙니다.","승용·화물용 승강기와 에스컬레이터이다":"승강기에는 승용·화물용 승강기와 에스컬레이터가 있습니다.","시각 식별 자극 차원으로 꼽히지 않는다":"강도는 시각 식별 자극 차원으로 꼽지 않습니다.","시각장치가 지나치게 많거나 즉각적인 행동이 필요할 때도 좋다":"시각장치가 지나치게 많거나 즉각 행동해야 할 때도 청각 표시가 낫습니다.","시각적 식별이 가능한 자극 차원은 형태·구성·위치이다":"시각적으로 식별할 수 있는 자극 차원은 형태, 구성, 위치입니다.","시간간격은 외기온 25℃ 미만에서 90분 이내이다":"수밀콘크리트 연속 타설 시간간격은 외기온 25℃ 미만에서 90분 이내입니다.","시간당 1cm 이상이면 중지하고 지진 진도 3 이상은 기준이 아니다":"눈이 시간당 1cm 이상 내리면 철골작업을 멈추며, 진도 3 이상 지진은 이 기준에 들어 있지 않습니다.","시간당 1mm 이상이면 중지한다":"시간당 1mm 이상 비가 오면 철골작업을 중지합니다.","시간·순서·정성적 착오가 포함되며 불필요한 수행은 extraneous error이다":"시간·순서·정성적 착오는 작위 오류에 들어가고, 필요 없는 수행은 extraneous error라 부릅니다.","시공 중 위험 정보 제공과 예측치·측정치 비교, 향후 거동 대책 수립이 목적이다":"계측은 시공 중 위험 정보를 주고 예측치와 측정치를 비교해 앞으로의 거동 대책을 세우려는 것입니다.","시멘트 액체방수보다 시공이 번잡하고 보수가 불편하나 내구성이 크다":"아스팔트방수는 시멘트 액체방수보다 시공이 번잡하고 보수가 불편하지만 내구성이 큽니다.","시멘트 창고 마루는 지상 30cm 이상 높게 설치한다":"시멘트를 쌓는 창고 바닥은 지면에서 30cm 이상 띄워 습기를 막습니다.","시선은 진행 방향을 향하고 뒷걸음 운반을 금하며 쌓인 하물의 중간·하부에서 뽑지 않는다":"시선은 진행 방향을 향하고 뒷걸음으로 나르지 않으며 쌓인 하물의 중간·하부에서 뽑지 않습니다.","시스템 고장 형태에는 오동작·개로(개방)·폐로(폐쇄) 고장이 있다":"시스템 고장은 오동작, 개로(개방) 고장, 폐로(폐쇄) 고장의 형태로 나타납니다.","시스템 분석에서 더 발전시켜야 하는 사상이다":"결함사상은 시스템 분석에서 앞으로 더 풀어 가야 하는 사상입니다.","시스템 안전업무는 안전활동의 계획·조직 및 관리가 필요하다":"시스템 안전업무는 안전활동을 계획하고 조직하고 관리하는 일이 필요합니다.","시스템이 고장나지 않게 하는 조합은 컷셋이 아니다":"고장 나지 않게 하는 사상의 조합은 패스셋이라 불러서 컷셋과 구별합니다.","시정방법 선정에는 기술적 개선·작업배치 조정·교육훈련 개선이 있다":"시정방법을 정할 때는 기술적 개선, 작업배치 조정, 교육훈련 개선 중에서 고릅니다.","식별이 어려운 통제기기를 선택하면 안 된다":"식별하기 어려운 통제기기는 고르면 안 됩니다.","신도는 스트레이트가 크고 블론은 작으며 온도 변화에 대한 감온성은 스트레이트가 크다":"신도는 스트레이트가 크고 블론이 작으며, 온도에 따른 변화는 스트레이트가 더 큽니다.","신청에는 보유 현황·검사 주기와 기준·향후 2년간 검사 수행 계획을 첨부한다":"자율검사프로그램 신청 때는 보유 현황, 검사 주기와 기준, 향후 2년간 검사 수행 계획을 붙입니다.","실천 가능하고 회사 방침과 일관되며 현장 특성에 맞게 구체적이어야 한다":"현장 특성에 맞게 구체적이고 회사 방침과 일관되며 실천 가능한 안전관리계획을 세웁니다.","실현가능성이 같은 2개의 대안 중 하나가 명시될 때 얻는 정보량이다":"이 정보량 단위는 가능성이 같은 2개 대안 중 하나가 정해질 때 얻는 양입니다.","심재보다 비중이 작고 신축성이 크며 강도·내구성이 약하다":"변재는 심재에 비해 비중이 작고 잘 늘고 줄며 강도와 내구성이 약합니다.","안료는 물에 녹지 않고 내알칼리성이어야 하며 테라조는 대리석·사문암 종석을 쓴다":"안료는 알칼리에 변하지 않고 물에 풀리지 않아야 하며, 테라조 종석으로는 대리석이나 사문암을 씁니다.","안전관리자 인건비·안전시설비·안전진단비·보호구 구입 수리비는 사용 가능하다":"안전관리자 인건비, 안전시설비, 안전진단비, 보호구 구입·수리비는 관리비로 쓸 수 있습니다.","안전교육이나 표준작업제도 도입은 의식의 우회 대책이 아니다":"의식의 우회는 교육이나 표준작업제도가 아니라 상담 같은 방법으로 풀어야 합니다.","안전담당자를 지정해 지도·감독하고 안전대 착용과 추락방지망을 설치한다":"추락재해 방지를 위해 안전담당자를 지정해 지도·감독하고 안전대와 추락방지망을 갖춥니다.","안전모 구성요소에는 턱끈·착장체·충격흡수재가 있다":"안전모는 턱끈, 착장체, 충격흡수재 등으로 구성됩니다.","안전모·안전화·방독마스크 착용이며 방호복 착용은 아니다":"지시표지는 안전모, 안전화, 방독마스크 착용을 알리며 방호복 착용은 해당하지 않습니다.","안전성·작업성·경제성을 갖추고 폭풍우 후에는 손상·연결상태를 점검한다":"비계는 안전성, 작업성, 경제성을 갖춰야 하며 폭풍우 뒤에는 손상과 연결상태를 점검합니다.","안전성 평가에는 위험 예측 평가·체크리스트 평가·고장 모드 영향분석이 있다":"고장 모드 영향분석과 위험 예측 평가, 체크리스트 평가를 안전성 평가 방법으로 둡니다.","안전조직·사실의 발견(위험소재 발견)·분석·시정방법 선정·적용이다":"하인리히는 안전조직, 사실의 발견, 분석, 시정방법 선정, 적용 순으로 단계를 나눴습니다.","암질 변화 구간은 R.Q.D·R.M.R 분류·탄성파 속도로 판별한다":"암질이 바뀌는 구간은 R.Q.D, R.M.R 분류, 탄성파 속도로 판별합니다.","암호표시가 인간의 기대와 모순되지 않는 것이다":"부호의 양립성은 암호표시가 인간의 기대와 모순되지 않는 것입니다.","압쇄기·대형 브레이커·쐐기 타입기(Rock jack)이다":"해체 기계·기구에는 압쇄기, 대형 브레이커, 쐐기 타입기(Rock jack)가 있습니다.","압접면을 그라인더로 평탄히 하고 항복점·재질이 다른 철근에는 적용하지 않는다":"철근 압접은 압접면을 그라인더로 고르게 다듬은 뒤 하며, 항복점·재질이 다른 철근끼리는 하지 않습니다.","압축강도＞전단강도＞인장강도이고 반발경도법·자기법·음파법은 비파괴 검사이다":"압축강도가 가장 크고 전단강도, 인장강도 순으로 작아지며 반발경도법·자기법·음파법은 비파괴 검사입니다.","양생철망·양생시트·방호선반이며 안전난간은 낙하물 방지설비가 아니다":"양생철망, 양생시트, 방호선반이 제삼자를 보호하는 설비이고 안전난간은 낙하물 방지설비가 아닙니다.","양식이 간단하고 적은 노력으로 특별한 훈련 없이 해석할 수 있다":"FMEA는 양식이 간단해 적은 노력으로 훈련 없이도 해석할 수 있습니다.","억압·공격·합리화가 포함되고 갈등은 아니다":"적응기제에는 억압, 공격, 합리화가 포함되고 갈등은 적응기제가 아닙니다.","얼음·드라이아이스 작업은 더운 물과 음식을 섭취하고 틈틈이 운동한다":"얼음이나 드라이아이스 작업은 더운 물과 음식을 먹고 틈틈이 운동하며 합니다.","연속 조절 통제기기는 노브·페달·핸들이고 토글스위치는 개폐용이다":"노브, 페달, 핸들은 연속으로 조절하는 통제기기이고 토글스위치는 열고 닫는 개폐용입니다.","연약한 점토지반에서 굴착면이 융기하는 현상이다":"히빙은 연약한 점토지반에서 굴착면이 부풀어 오르는 현상입니다.","열전도율이 보통콘크리트의 약 1/10이고 절건비중이 0.45~0.55이다":"ALC는 열이 잘 통하지 않아 열전도율이 보통콘크리트의 약 1/10에 그치고 절건비중은 0.45~0.55입니다.","염해·중성화·동해이고 백화는 아니다":"내구성 저하 요인에는 염해, 중성화, 동해가 있으며 백화는 포함되지 않습니다.","오버랩·언더컷·블로홀이고 가우징은 결함이 아니다":"용접결함에는 오버랩, 언더컷, 블로홀이 있고 가우징은 결함이 아니라 가공 방법입니다.","오픈 컷·트렌치 컷·아일랜드 컷이고 톱다운은 모양 분류가 아니다":"흙파기공법에는 오픈 컷, 트렌치 컷, 아일랜드 컷이 있고 톱다운은 모양 분류가 아닙니다.","온도가 높고 분말도가 크고 신선할수록 빠르며 수량이 많으면 느리다":"시멘트 응결은 온도가 높고 분말도가 크고 신선할수록 빠르며 물이 많으면 늦습니다.","완충재·부드러운 마감재·이중바닥으로 줄이고 슬래브 중량은 크게 한다":"바닥충격음은 완충재, 부드러운 마감재, 이중바닥으로 줄이고 슬래브를 무겁게 합니다.","외벽에는 유성페인트·에나멜페인트·합성수지 에멀션페인트가 적합하고 바니시는 아니다":"바니시는 외벽에 맞지 않고 유성페인트, 에나멜페인트, 합성수지 에멀션페인트가 외벽용으로 알맞습니다.","외부습도가 높을수록 크리프가 작고 부재 치수가 클수록 작다":"크리프는 외부습도가 높거나 부재 치수가 클수록 덜 일어납니다.","외이는 외이도·귓바퀴이고 내이는 난원창·청신경, 달팽이관은 기저막이 진동한다":"외이는 외이도·귓바퀴, 내이는 난원창·청신경으로 이루어지며 달팽이관에서는 기저막이 진동합니다.","요소 하나만 정상이어도 계가 정상이고 중복도가 늘수록 수명이 길다":"병렬계는 요소 하나만 살아 있어도 정상이고 중복도를 높일수록 수명이 길어집니다.","욕구는 생리적·안전·사회적 욕구 등으로 나뉘고 심리적 욕구는 단계가 아니다":"욕구의 단계 이름에 심리적 욕구는 없으며 생리적, 안전, 사회적 욕구 등으로 구분합니다.","용기 안 골재 입자가 차지하는 실용적의 백분율이며 클수록 페이스트량이 적게 든다":"실적률은 용기 부피 중 골재 알이 채운 비율이며 클수록 틈이 적어 페이스트가 덜 듭니다.","용접부에서 100mm 이내에 칠하지 않으며 콘크리트에 묻히는 부분에도 칠하지 않는다":"콘크리트에 묻히는 부분과 현장 용접부 주변 100mm 안쪽에는 녹막이칠을 하지 않습니다.","우물통(Open)·공기(Pneumatic)·상자형(Box) 케이슨이 있고 피어는 아니다":"케이슨은 우물통(Open), 공기(Pneumatic), 상자형(Box) 세 가지이고 피어는 포함되지 않습니다.","운반대 같은 보조구를 쓰고 수평거리 운반을 원칙으로 한다":"운반대 같은 보조구를 쓰고 수평거리로 옮기는 것을 원칙으로 합니다.","운반 시 몸을 반듯이 펴고 등을 편 상태로 들고 내리며 짐을 몸에 가깝게 든다":"운반할 때는 몸과 등을 반듯이 편 채로 들고 내리며 짐을 몸에 가깝게 듭니다.","운전위치를 이탈할 때는 원동기를 정지하고 브레이크를 건다":"운전위치를 떠날 때는 원동기를 끄고 브레이크를 걸어 둡니다.","운전자 1명으로 하역·운반이 가능하고 50m 이내 운반에서 효율이 높다":"지게차는 운전자 한 명으로 하역과 운반을 하며 50m 이내 운반에서 효율이 높습니다.","운전자가 보기 쉬운 곳에 운전속도·정격하중·경고표시를 붙인다":"크레인에는 운전자가 보기 쉬운 곳에 운전속도, 정격하중, 경고표시를 붙입니다.","울타리나 수직형 추락방망도 방호조치이다":"울타리나 수직형 추락방망도 개구부의 방호조치에 속합니다.","원리는 교대 구조·다경로하중 구조·하중경감 구조이다":"페일세이프 원리에는 교대 구조, 다경로하중 구조, 하중경감 구조가 있습니다.","웰포인트로 지하수위를 낮추고 약액주입으로 굴착지면을 지수한다":"지하수를 뽑아 수위를 낮추고 약액주입으로 굴착지면을 막아 물이 새지 않게 합니다.","위생도기·테라코타·타일은 점토제품이고 테라조는 점토제품이 아니다":"위생도기, 테라코타, 타일은 점토제품이지만 테라조는 시멘트 계열이라 점토제품이 아닙니다.","위생요인은 직무 만족의 주요인이 아니다":"위생요인은 직무 만족을 이끄는 주된 요인이 되지 못합니다.","위험 파악·위험 처리·사고 발생 확률 예측이다":"위험관리는 위험을 파악하고 처리하며 사고 발생 확률을 예측하는 일을 합니다.","유리블록은 균일한 확산광을 얻고 스테인드 글라스는 단열성이 우수하지 않다":"스테인드 글라스는 단열이 좋지 않고, 유리블록은 빛을 고르게 퍼뜨립니다.","유족급여와 직업재활급여도 직접비이다":"직업재활급여와 유족급여도 직접비로 셉니다.","유해요인 수시조사는 질환자 발생·새 설비 도입·작업환경 변경 때 한다":"유해요인 수시조사는 질환자가 생기거나 새 설비를 들이거나 작업환경이 바뀔 때 합니다.","육체적 요구조건·작업환경 조건·보건상 위험성을 고려한다":"위험작업분석은 육체적 요구조건, 작업환경 조건, 보건상 위험성을 고려합니다.","의미 없는 내용은 의미 있는 내용보다 빨리 망각한다":"내용이 뜻을 갖지 못하면 금방 잊히며 의미 있는 내용보다 망각이 빠릅니다.","의식의 우회에는 상담이 예방대책이다":"의식의 우회는 걱정 같은 일 때문에 일에 집중하지 못하는 상태라 상담이 예방대책입니다.","의자의 깊이·너비를 작은 사람 기준으로 하지 않고 평균치 설계를 먼저 고려하지도 않는다":"의자 깊이·너비는 작은 사람 기준이 아니고, 평균치 설계를 우선 고려하지도 않습니다.","이동이 잦거나 큰 힘·중량물 취급이 필요한 작업에 좋고 안정감이 필요하면 앉는다":"서서 하는 자세는 이동이 잦거나 큰 힘을 쓰거나 무거운 물건을 다루는 작업에 좋고 안정감이 필요하면 앉습니다.","이어붓기를 피하고 높은 곳에서 자연낙하시키면 안 된다":"최상부 슬래브는 이어붓기를 피하고 높은 곳에서 자연낙하시켜 치지 않습니다.","이완된 지표면을 다지고 콘크리트 두께를 절약하며 폭이 기초보다 넓다":"잡석지정은 이완된 지표면을 다지고 콘크리트 두께를 아끼며 폭이 기초보다 넓습니다.","이음 길이는 갈고리 중심 간 거리이며 경미한 압축근은 지름의 20배로 할 수 있다":"이음 길이는 갈고리 중심 사이를 재며, 경미한 압축근에 한해 지름의 20배로 정할 수 있습니다.","이음매가 있거나 꼬인 와이어로프는 쓰지 않는다":"이음매가 있는 와이어로프와 꼬인 와이어로프는 사용하지 않습니다.","이종 금속을 접촉시키지 않고 표면을 매끄럽고 건조하게 둔다":"부식을 줄이려면 서로 다른 금속을 접촉시키지 않고 표면을 매끄럽고 건조하게 둡니다.","인간과 기계의 조화성은 지적·신체적·감성적 조화성이다":"인간과 기계의 조화성은 지적, 신체적, 감성적 조화성으로 나뉩니다.","인간 실수는 우발적으로 재발하고 인간은 학습으로 성능이 향상되지만 기계 고장은 저절로 복구되지 않는다":"인간 실수는 우발적으로 되풀이되고 사람은 학습으로 성능이 오르지만 기계 고장은 스스로 복구되지 않습니다.","인간 실수의 출력 착오는 신체적 반응의 착오이고 감각·입력의 착오는 아니다":"출력 착오는 사람이 몸으로 잘못 반응한 착오이며 감각이나 입력의 착오는 아닙니다.","인간실수확률 추정기법은 THERP이다":"인간실수확률 추정기법으로는 THERP를 꼽습니다.","인간실수확률 추정기법이 아니다":"PHA는 위험을 미리 분석하는 기법이어서 인간실수확률 추정기법이 아닙니다.","인간은 글씨보다 그림을 더 잘 인식하고 시각으로 가장 많은 정보를 받는다":"사람은 글씨보다 그림을 더 쉽게 받아들이고 시각으로 가장 많은 정보를 얻습니다.","인간이 본래 일을 싫어하고 명령받기를 좋아하며 책임을 회피한다고 본다":"X이론은 사람이 원래 일을 꺼리고 지시받기를 바라며 책임지기를 피한다고 가정합니다.","인간 특성과 한계를 고려해 제품을 설계하며 사고 방지와 능률·편리성을 높인다":"인간공학은 인간의 특성과 한계를 고려해 제품을 설계하여 사고를 막고 능률과 편리성을 높입니다.","인양 물체 안정을 위해 2줄 걸이 이상을 쓰고 물체 위에 근로자를 태우지 않는다":"인양할 때는 물체를 안정시키려고 2줄 걸이 이상을 쓰고 물체 위에 사람을 태우지 않습니다.","인장강도는 탄소량 0.85% 정도에서 최대이며 계속 증가하지 않는다":"인장강도는 탄소량 0.85% 정도에서 가장 크고 그 뒤로는 더 늘지 않습니다.","인접한 기존 건물 기초가 얕아 보강할 때는 언더피닝 공법을 쓴다":"언더피닝은 이웃한 기존 건물 기초가 얕을 때 그 기초를 보강하는 공법입니다.","인체계측 응용원칙은 조절범위·최대최소치수·평균치 설계이다":"인체계측 자료는 조절범위, 최대·최소치수, 평균치 설계 원칙으로 응용합니다.","일식도급보다 경비가 줄어드는 것은 아니다":"공동도급은 일식도급과 달리 경비가 줄어드는 방식이 아닙니다.","일정계획표와 자재관리표는 보전기록 자료가 아니다":"보전 기록으로 쓰지 않는 자료가 일정계획표와 자재관리표입니다.","임의 점에서 100kg 이상 하중을 견뎌야 하며 기준은 50·80kg이 아니다":"안전난간은 임의의 점에서 100kg 이상 하중을 견뎌야 하며 50kg, 80kg은 기준이 아닙니다.","입경·유체 점성계수·공극비·유체 밀도이며 압축지수는 아니다":"투수계수는 입경, 유체 점성계수, 공극비, 유체 밀도에 영향을 받으며 압축지수는 해당하지 않습니다.","입력 발생 후 일정 시간이 지속되어야 출력이 나온다":"위험 지속 기호는 입력이 생긴 뒤 일정 시간 이어져야 출력이 나오는 게이트입니다.","입찰 일시·장소, 개략 공사 규모, 발주자·설계자 명칭이 들어가고 분쟁 해결방법은 아니다":"입찰공고에 적는 것은 입찰 일시와 장소, 개략 공사 규모, 발주자·설계자 명칭이고 분쟁 해결방법은 없습니다.","자갈 최대지름 25mm 이하이며 박리제를 충분히 쓴다":"제치장 콘크리트는 자갈 최대지름 25mm 이하로 하고 박리제를 충분히 씁니다.","자기 반성·대화로 해결책 모색·가급적 빨리 풀기이다":"스트레스는 자기 반성, 대화로 해결책 모색, 가급적 빨리 풀기로 해소합니다.","자기통제·책임감·창조력을 보고 직무확장과 목표에 의한 관리를 쓴다":"Y이론은 자기통제, 책임감, 창조력을 믿고 직무확장과 목표에 의한 관리를 씁니다.","자료시방서는 제조업자 작성, 성능시방서는 필요 성능만 명시, 개략시방서는 설계 초기용이다":"제조업자가 쓰는 시방서가 자료시방서, 필요한 성능만 밝히는 것이 성능시방서이고 개략시방서는 설계 초기에 씁니다.","자립식·수평버팀·타이로드 및 어스앵커 공법이 있다":"흙막이 공법에는 자립식, 수평버팀, 타이로드 및 어스앵커 공법이 있습니다.","자재·노무·위험 및 재해방지이다":"공무적 현장관리는 자재, 노무, 위험 및 재해방지를 다룹니다.","자재비·외주비·노무비이고 일반관리비는 포함되지 않는다":"직접공사비는 자재비, 외주비, 노무비로 이루어지고 일반관리비는 여기에 넣지 않습니다.","자존심 손상·업무상 죄책감·현실 부적응이다":"내적 자극 요인은 자존심 손상, 업무상 죄책감, 현실 부적응입니다.","자중이 적고 내화성이 크며 열전도율이 낮고 방음효과가 크다":"경량콘크리트는 자중이 작고 열이 잘 안 통하며 내화성과 방음 효과가 큽니다.","작업 관련이 도시되어 전체와 부분 파악이 쉽다":"네트워크 공정표는 작업 관련이 그려져 전체와 부분을 파악하기 쉽습니다.","작업 구역에는 관계 근로자 외 출입을 금하고 악천후에는 작업을 중지한다":"동바리 작업 구역에는 관계 근로자만 들어가게 하고 날씨가 나쁘면 일을 멈춥니다.","작업대·비계에는 작업발판과 난간대를 설치한다":"작업대와 비계에는 발판과 난간대를 갖춰야 추락하지 않습니다.","작업대사량÷기초대사량이고 산소소모량은 더글라스백으로 잰다":"RMR은 작업대사량을 기초대사량으로 나눈 값이며 산소소모량은 더글라스백으로 잽니다.","작업대사량÷기초대사량이고 작업대사량은 작업 시와 안정 시 소비에너지의 차이다":"RMR은 작업대사량을 기초대사량으로 나눈 값이며 작업대사량은 작업 때와 안정 때 소비에너지의 차입니다.","작업대에 가드 또는 과상승방지장치를 설치하고 정격하중(안전율 5 이상)을 표시한다":"작업대에는 가드나 과상승방지장치를 달고 정격하중(안전율 5 이상)을 눈에 띄게 표시합니다.","작업면에서 가깝게 수평 설치, 처짐은 짧은 변 길이의 12% 이상, 수직거리는 10m 이하이다":"방망은 작업면 가까이 수평으로 설치하고, 처짐은 짧은 변의 12% 이상, 수직 간격은 10m 이하로 둡니다.","작업면 조도는 150럭스 이상이다":"보통작업의 작업면 조도는 150럭스 이상이어야 합니다.","작업면 조도는 300럭스 이상이다":"정밀작업의 작업면 조도는 300럭스 이상이어야 합니다.","작업발판과 안전관리계획서 작성비용, 안전담당자 업무수당 외 인건비는 아니다":"작업발판 설치, 계획서 작성비, 안전담당자 수당 외 인건비는 사용 가능한 항목이 아닙니다.","작업발판·안전대·안전망이고 버팀대는 아니다":"추락방지 설비는 작업발판, 안전대, 안전망이고 버팀대는 해당하지 않습니다.","작업발판·통로 끝이나 개구부에는 안전난간을 설치한다":"작업발판이나 통로 끝, 개구부에는 안전난간을 설치합니다.","작업부하를 크게 하는 것은 대책이 아니며 기계의 색·종류·조작부 배치가 피로에 영향을 준다":"작업부하를 키우면 오히려 피로가 쌓이며, 기계의 색과 종류, 조작부 배치가 피로에 영향을 줍니다.","작업상황 개선·요원변경·체계(시스템)의 영향 감소이다":"인간실수 예방기법은 작업상황 개선, 요원변경, 체계(시스템)의 영향 감소입니다.","작업속도를 적절히 하고 근로시간과 휴식을 적정하게 한다":"피로를 줄이려면 작업속도를 알맞게 하고 근로시간과 휴식을 적정하게 둡니다.","작업순서 관계가 명확해 공사담당자 간 정보전달이 원활하다":"작업순서 관계가 분명해 공사담당자 사이에 정보가 잘 전달됩니다.","작업순서를 정하고 악천후에는 중지하며 충분한 공간을 확보한다":"크레인 조립·해체는 작업순서를 정하고 악천후에는 중지하며 충분한 공간을 확보합니다.","작업순환·작업 윤택화·작업확대이다":"작업 만족도를 높이는 수단은 작업순환, 작업 윤택화, 작업확대입니다.","작업 시 소비에너지에서 안정 시 소비에너지를 뺀 값이다":"작업대사량은 작업할 때 소비에너지에서 가만히 있을 때 소비에너지를 뺀 값입니다.","작업영역의 조정 대상은 작업대·공구·작업자 자세이고 작업대상물은 아니다":"작업영역에서 조정하는 것은 작업대, 공구, 작업자 자세이고 작업대상물은 아닙니다.","작업요령을 효율적으로 익히고 추지도 교육이 가능하나 다수 조직 훈련은 어렵다":"O.J.T는 작업요령을 효율적으로 익히고 추지도도 가능하나 다수를 조직적으로 훈련하기는 어렵습니다.","작업자는 안전모·안전대 등 보호구를 착용한다":"고소작업대 작업자는 안전모와 안전대 같은 보호구를 착용합니다.","작업자 자신으로부터 발생하는 에러이다":"Primary error는 작업자 자신에게서 발생하는 에러입니다.","작업장을 정돈하고 피로한 근로자는 쉬게 하며 작업시간을 자유롭게 하는 것은 대책이 아니다":"작업장 정돈과 피로한 근로자의 휴식이 대책이며 작업시간을 자유롭게 두는 것은 대책이 아닙니다.","작업지도(JIT)·작업방법(JMT)·인간관계(JRT) 훈련이다":"TWI는 작업을 지도하는 JIT, 방법을 개선하는 JMT, 인간관계를 다루는 JRT 세 훈련으로 구성됩니다.","작업하중과 충격하중도 설계하중에 포함한다":"작업하중과 충격하중도 바닥판·보 거푸집의 설계하중에 넣습니다.","작업환경 개선(JET)·사례연구 훈련은 TWI 내용이 아니다":"TWI는 JET와 사례연구 훈련을 내용으로 하지 않습니다.","작업환경·보호조치·작업장소의 결함은 불안전 상태이다":"작업환경, 보호조치, 작업장소에 결함이 있는 것은 불안전 상태에 해당합니다.","작용응력·물시멘트비가 클수록, 재하 재령이 빠를수록 크다":"작용응력과 물시멘트비가 크고 재하 재령이 빠를수록 크리프가 큽니다.","작은 눈금과 겹치지 않게 하고 눈금면에서 멀리 두지 않는다":"지침 끝은 작은 눈금과 겹치지 않게 하되 눈금면에서 멀리 두지는 않습니다.","작은보 주근은 기둥이 아니라 큰보에 정착하고 보의 주근은 벽체에 정착하지 않는다":"큰보가 작은보 주근을 받아 정착시키며, 기둥이 받는 것은 아니고 보 주근을 벽체에 정착하지도 않습니다.","장치는 설계·제작 사양대로 제작된 것으로 간주하며 전기설비 위험성 평가법이 아니다":"HAZOP은 장치가 설계·제작 사양대로 만들어졌다고 전제하며 전기설비 위험성 평가법은 아닙니다.","장해등급 1~3급에 해당한다":"장해등급 1~3급은 일을 전혀 할 수 없는 영구 전노동 불능 상해에 해당합니다.","재료를 직접 불꽃으로 가열하지 않고 동결된 지반은 녹인 뒤 타설한다":"재료를 불꽃으로 직접 가열하지 않고 얼어붙은 지반은 녹인 뒤 타설합니다.","재료비·노무비·경비의 합계액이다":"공사원가는 재료비, 노무비, 경비를 더한 금액입니다.","재료·장비·설비의 유형과 품질, 조립·설치 방법, 시험 및 코드 요건을 적는다":"시방서에는 재료·장비·설비의 종류와 품질, 시공 방법, 시험과 코드 요건을 담습니다.","재해 발생원인 조사 및 대책 수립, 안전교육계획 수립 및 실시를 한다":"안전관리자는 재해 발생원인 조사와 대책 수립, 안전교육계획 수립과 실시를 맡습니다.","재해 발생 형태에는 집중형·연쇄형·복합형이 있다":"재해는 집중형, 연쇄형, 복합형의 발생 형태로 나눕니다.","재해방지 원칙은 예방 가능·손실 우연·대책 선정·원인 계기의 원칙이다":"재해방지 원칙은 예방 가능, 손실 우연, 대책 선정, 원인 계기를 이르는 네 원칙입니다.","재해 보고 및 응급조치와 환기장치 점검은 안전관리자 업무가 아니다":"안전관리자의 업무에 재해 보고·응급조치와 환기장치 점검은 들지 않습니다.","적성 배치·이해와 납득·항상 모범·청취 위주 대화이다":"태도교육 원칙은 적성 배치, 이해와 납득, 항상 모범, 청취 위주 대화입니다.","적정량·올바른 윤활법·윤활기간 준수이며 윤활제를 혼합하지 않는다":"윤활제를 섞지 않고 적정량을 올바른 방법으로 정해진 기간에 주는 것이 윤활의 원칙입니다.","전기 용접·굳지 않은 콘크리트·감전 위험 작업에 쓰고 드릴 작업에는 끼지 않는다":"안전장갑은 전기 용접, 굳지 않은 콘크리트, 감전 위험 작업에 끼고 드릴 작업에는 끼지 않습니다.","전기저항이 크고 열전도율이 낮으며 먼지가 잘 끼지 않아 청소하기 쉽다":"열은 잘 전하지 않고 전기저항이 큰 스테인리스강은 먼지가 잘 끼지 않아 청소가 쉽습니다.","전기적 암호화나 무게는 촉각적 암호화 특성이 아니다":"촉각적 암호화에서는 전기적 암호화나 무게가 특성에 들지 않습니다.","전단력 전달용 철물이며 인장력 전달용이 아니다":"듀벨은 전단력을 전달하는 철물이고 인장력을 전달하는 용도는 아닙니다.","전도·화약 발파·팽창압 공법이고 오픈컷은 아니다":"해체 공법에는 전도, 화약 발파, 팽창압 공법이 있고 오픈컷은 굴착 공법입니다.","전문가를 초빙해 다수 근로자를 조직적으로 훈련하며 지식·경험을 교류한다":"Off.J.T는 전문가를 불러 많은 근로자를 조직적으로 훈련하고 지식과 경험을 나눕니다.","전선이 바뀌거나 틀린 부품·거꾸로 조립된 부품처럼 잘못 수행한 경우이다":"전선을 바꿔 달았거나 틀린 부품을 쓰거나 부품을 거꾸로 조립한 것이 작위 오류입니다.","전완과 상완을 곧게 펴서 파악할 수 있는 영역이다":"최대작업영역은 전완과 상완을 곧게 펴서 닿는 영역입니다.","전용 횟수를 높이는 것이 합리적 방향이다":"거푸집을 여러 번 다시 쓰는 전용 횟수를 높이는 것이 합리적인 방향입니다.","전쟁·재해·질병 같은 위협에서 벗어나려는 욕구이고 궁극은 자아실현이다":"안전 욕구는 전쟁, 재해, 질병 같은 위협에서 벗어나려는 욕구이고 맨 위 단계는 자아실현입니다.","전 종업원의 안전요원화나 작업조건의 기술적 개선은 3요소가 아니다":"전 종업원을 안전요원으로 삼는 것이나 작업조건의 기술적 개선은 추진 요소가 아닙니다.","절단면은 측선에 수직으로 하고 흠이 있으면 그라인더로 갈며 수동절단도 경미한 공사에 쓴다":"절단면은 측선에 수직으로 하고 흠이 있으면 그라인더로 갈며 경미한 공사는 수동절단도 씁니다.","절·성토 높이 증가, 사면 경사 증가, 지표수·지하수 침투로 인한 중량 증가이다":"토사 붕괴의 외적 원인은 절·성토 높이와 사면 경사의 증가, 침투수로 인한 중량 증가입니다.","점검·정비보존 불량, 생산공정 부적당, 구조·재료 부적합이다":"점검·정비보존이 불량하거나 생산공정이 부적당하거나 구조·재료가 맞지 않으면 기술적 원인입니다.","점토는 비중 2.5~2.6이고 건조하면 수축하며 건조수축·소성변형이 크다":"점토는 비중이 2.5~2.6이고 마르면 줄어드는 성질이 있어 건조수축과 소성변형이 큽니다.","점토 입자가 미세할수록 가소성이 커지고 압축강도는 인장강도의 약 5배이다":"입자가 고운 점토일수록 반죽이 잘 빚어지는 가소성이 크고, 눌림 강도가 당김 강도의 약 5배입니다.","정량 처리와 시각적 정보 전달이 가능하고 귀납적 추리도 가능하다":"FTA류는 정량 처리와 시각적 정보 전달이 가능하고 귀납적 추리도 할 수 있습니다.","정밀 작업용 손잡이를 5mm 이하로, 힘을 요하는 손잡이를 60mm 이상으로 하는 것도 원칙이 아니다":"정밀 작업 손잡이는 5mm 이하, 힘 쓰는 손잡이는 60mm 이상이라는 수치도 원칙이 아닙니다.","정상사상을 발생시키는 기본사상의 조합이며 시스템의 약점을 나타낸다":"컷셋은 정상사상을 일으키는 기본사상의 조합이어서 시스템의 약점을 보여 줍니다.","정서 불안정·감각차단·생리·심리적 능력의 한계이며 기능미숙은 아니다":"인지과정 착오의 요인은 정서 불안정, 감각차단, 생리·심리적 능력 한계이며 기능미숙은 아닙니다.","정신적·신체적·관리적 원인이고 물적 원인은 직접원인이다":"간접원인은 정신적·신체적·관리적 원인이며 물적 원인은 직접원인에 속합니다.","정적 인체치수는 마틴식 측정기로 재고 동적 치수는 신체 움직임에 따른 활동범위를 잰다":"마틴식 측정기로 정적 인체치수를 재고, 동적 치수는 신체를 움직이며 닿는 활동범위를 잽니다.","정적 재해는 낙하·붕괴·추락이고 충돌은 동적 재해이다":"낙하·붕괴·추락은 정적 재해이고 충돌은 동적 재해로 구분합니다.","정첩·도어체크·도어스톱·플로어 힌지·지도리·걸쇠는 창호용 철물이고 인서트는 아니다":"인서트는 창호용이 아니라 콘크리트에 묻는 철물이고, 정첩·도어체크·도어스톱·플로어 힌지·지도리·걸쇠가 창호용입니다.","제거·결합·재배치·단순화이고 교육(Education)은 아니다":"ECRS는 제거, 결합, 재배치, 단순화이고 교육(Education)은 포함되지 않습니다.","제거한 거푸집은 재사용하게 정리하고 남은 쪽널을 그대로 두고 미장하지 않는다":"떼어 낸 거푸집은 재사용하게 정리하고, 남은 쪽널을 그대로 둔 채 미장하지 않습니다.","제시는 도입 뒤에 오고 확인은 마지막에 온다":"교시법에서 제시는 도입 다음에, 확인은 마지막에 합니다.","제어(회피·손실제어·분리·책임전가)와 재정 처리(보유·전가)이며 비용을 고려한다":"위험은 제어(회피·손실제어·분리·책임전가) 또는 재정 처리(보유·전가)로 다루고 비용을 함께 따집니다.","제작 비용과 제동장치 점검은 작업계획 내용이 아니다":"작업계획서에 제작 비용과 제동장치 점검은 내용으로 넣지 않습니다.","제치장 콘크리트의 벽·기둥은 한 번에 꼭대기까지 붓고 빈배합으로 하지 않는다":"제치장 콘크리트는 벽·기둥을 꼭대기까지 한 번에 붓고 빈배합은 쓰지 않습니다.","조도는 거리에 반비례하며 휘도 단위는 Lambert·foot-Lambert·nit(cd/m²)이다":"조도는 광원에서 멀어질수록 낮아지며 휘도 단위는 Lambert, foot-Lambert, nit(cd/m²)입니다.","조작거리와 일치성은 고려요소가 아니며 계기 크기를 항상 작게 설계하지 않는다":"조작거리와 일치성은 고려하지 않으며, 계기 크기를 일률적으로 작게 하는 것도 아닙니다.","조정장치를 반시계 방향으로 돌리는 것은 켤 때의 기대 방향이 아니다":"스위치는 위로, 버튼은 오른쪽으로, 조종장치는 앞으로 미는 것이 켤 때 사람이 기대하는 움직임입니다.","조종장치의 촉각적 암호화는 형상·크기·표면촉감 암호화이다":"조종장치의 촉각적 암호화는 형상, 크기, 표면촉감으로 구별하게 하는 것입니다.","종석·백색 포틀랜드시멘트·안료·돌가루로 배합한다":"인조석바름은 종석, 백색 포틀랜드시멘트, 안료, 돌가루를 섞어 만듭니다.","종업원의 정화(Catharsis) 작용을 촉진한다":"모랄 서베이는 종업원이 속마음을 털어놓는 정화(Catharsis) 작용을 돕습니다.","주관적·객관적·생리적 피로가 있다":"피로는 주관적 피로, 객관적 피로, 생리적 피로로 나뉩니다.","주물 및 단조작업은 특별안전보건교육 대상이다":"주물 및 단조작업은 특별안전보건교육을 해야 하는 작업입니다.","주변 도로 분포나 굴착기 이상 유무는 사전조사 항목이 아니다":"굴착 전에 살필 대상은 땅과 지하 매설물이고 주변 도로 분포나 굴착기 이상 유무는 아닙니다.","주요 위험요인은 부적절한 자세·과도한 힘·단시간의 많은 반복이다":"근골격계 위험요인은 부적절한 자세, 과도한 힘, 짧은 시간의 많은 반복입니다.","준비성의 원리와 시행착오의 원리는 조건반사설 원리가 아니다":"조건반사설에서는 준비성의 원리와 시행착오의 원리를 원리로 꼽지 않습니다.","중복설계·충분한 여유용량·부품 개선으로 높인다":"신뢰도는 중복설계, 충분한 여유용량, 부품 개선으로 높입니다.","중앙 신경 처리 임무는 진동 영향을 덜 받고 목(경부골) 공명은 3~4Hz이다":"목(경부골)의 공명은 3~4Hz에서 일어나고, 중앙 신경 처리 임무는 진동을 덜 탑니다.","중요도와 사용빈도가 높은 것을 우선 배치하고 기능별로 그룹화한다":"중요도와 사용빈도가 높은 것을 먼저 배치하고 기능별로 묶습니다.","중요성·사용빈도·기능별 배치·사용순서이다":"부품 배치의 원칙은 중요성, 사용빈도, 기능별 배치, 사용순서를 기준으로 삼습니다.","중용열·조강·내황산염이며 중용열은 내침식성·내구성이 크다":"KS 포틀랜드 시멘트에는 중용열, 조강, 내황산염이 있고 중용열은 내침식성과 내구성이 큽니다.","중이는 고막이 아니라 추골·침골·등골로 이루어진다":"고막은 중이가 아니고, 추골·침골·등골 세 뼈가 중이를 이룹니다.","지도자가 모든 정책을 결정하는 것은 권위형이다":"정책을 모두 혼자 정하는 지도자는 권위형입니다.","지름 감소가 공칭지름의 7%를 넘으면 사용할 수 없다":"지름 감소가 공칭지름의 7%를 넘은 와이어로프는 쓸 수 없습니다.","지보공을 설치하고 부석을 제거한다":"갱내 측벽 붕괴는 지보공을 설치하고 부석을 제거해 막습니다.","지상 높이 31m 이상 건축물·공작물 공사는 계획서 제출 대상이다":"지상 높이 31m 이상 건축물·공작물 공사는 유해위험방지계획서를 내야 합니다.","지상 첫 띠장은 2m 이하에 설치하고 비계기둥 적재하중은 400kg을 넘기지 않는다":"비계에서 지상의 첫 띠장은 2m 이하에 달고, 기둥 한 곳에 400kg 넘는 짐을 싣지 않습니다.","지수성이 좋고 강성이 커 변형이 적으나 공사비가 많이 든다":"지중연속벽은 물이 새지 않고 강성이 커 변형이 적은 대신 공사비가 많이 듭니다.","지정 지반면에서 0.5~1m 위치에 두고 높이를 적어 둔다":"기준점은 지정 지반면에서 0.5~1m 높이에 두고 거기에 높이를 적어 둡니다.","지주를 바꿔 세울 동안 상부 작업을 제한해 적재하중을 줄인다":"지주를 바꿔 세우는 중에는 상부 작업을 제한해 적재하중을 줄여 둡니다.","지주부재와 수평면의 기울기는 75° 이하로 한다":"말비계 지주부재와 수평면 사이 기울기는 75° 이하로 합니다.","지지력이 크고 이음이 안전하며 경량이고 상부구조와 결합이 쉽다":"강관말뚝은 지지력이 크고 이음이 안전하며 가볍고 상부구조와 쉽게 결합됩니다.","지침 색을 선단에서 눈금 중심까지 칠한다":"원형 눈금의 지침 색은 선단에서 눈금 중심까지 칠합니다.","지휘 형태는 민주주의적이고 조직원에 의해 선출된다":"리더십은 민주주의적 방식으로 이끌고 조직원이 직접 뽑는 지도자입니다.","직경 1.3cm·두께 0.95cm 정도에서 구별 가능하다":"직경 1.3cm, 두께 0.95cm 정도의 차이에서 촉각으로 구별할 수 있습니다.","직무 만족의 주요인이며 일의 내용·책임감이 해당한다":"동기요인은 직무 만족의 주요인이며 일의 내용과 책임감이 해당합니다.","직장 대인관계 갈등은 외적 요인이며 스트레스는 직무몰입과 생산성 감소의 원인이 된다":"직장 대인관계 갈등은 외적 요인이고, 스트레스가 쌓이면 직무몰입과 생산성이 떨어집니다.","직장 실정에 맞는 실제적 훈련은 Off.J.T가 아니라 O.J.T의 특징이다":"실제 직장 사정에 맞춘 훈련은 O.J.T의 특징이며 Off.J.T의 특징이 아닙니다.","직접노무비와 간접노무비로 나뉘고 직접노무비에는 기본급·제수당·퇴직급여가 든다":"직접노무비에 기본급·제수당·퇴직급여가 들며, 노무비는 직접과 간접으로 나뉩니다.","직접 손실비는 요양급여·휴업급여·간병급여이다":"요양급여, 휴업급여, 간병급여가 직접 손실비에 해당하는 급여입니다.","직접 점화하는 것은 안전담당자의 직무가 아니다":"발파 안전담당자가 직접 점화하는 것은 직무가 아닙니다.","진동기로 다지면 측압이 커지고 기둥이 벽보다 크다":"진동기로 다지면 측압이 커지고 같은 조건에서 기둥이 벽보다 측압이 큽니다.","진동다짐한 콘크리트는 보통콘크리트보다 강도가 커진다":"진동으로 다진 콘크리트는 빈틈이 줄어 보통 다짐 콘크리트보다 강도가 커집니다.","진동은 진폭에 비례해 시력을 손상시키며 10~25Hz에서 가장 심하다":"진동은 진폭이 클수록 시력을 더 해치고 10~25Hz에서 가장 심합니다.","진동·충격을 주지 않고 콘크리트가 손상되지 않게 순서대로 제거한다":"거푸집은 진동·충격을 주지 않고 콘크리트가 다치지 않게 순서대로 뗍니다.","진폭에 비례해 나빠지고 5Hz 이하에서 가장 심하며 정밀 근육 조절 작업도 저하된다":"추적 능력은 진폭에 비례해 나빠지고 5Hz 이하에서 가장 크게 떨어지며 정밀 근육 조절도 저하됩니다.","진폴·가이데릭·스티프레그데릭":"철골 세우기 장비에는 진폴, 가이데릭, 스티프레그데릭이 있습니다.","집단토론이나 집단결정을 통해 정책을 결정한다":"민주형 리더는 집단토론이나 집단결정을 통해 정책을 결정합니다.","차량계 건설기계의 종류·성능, 운행경로, 작업방법이 들어간다":"차량계 건설기계 작업계획서에는 기계의 종류와 성능, 운행경로, 작업방법이 들어갑니다.","참가자가 자주적·적극적이 되고 동기 부여가 쉬우며 태도 교육이 쉽다":"토의식 교육은 참가자가 자주적·적극적이 되어 동기 부여와 태도 교육이 쉽습니다.","참모식은 라인식보다 비경제적이며 명령이 생산계통을 따르는 것은 라인식이다":"라인식은 명령이 생산계통을 따르고, 참모식은 그렇지 않아 라인식보다 비용이 더 듭니다.","창유리 강도는 휨강도이고 열선반사유리는 금속피막을 입히며 방탄유리는 강화유리를 합유리화한다":"창유리 강도는 휨강도로 말하고 열선반사유리는 금속피막을, 방탄유리는 합유리화한 강화유리를 씁니다.","채광·통풍을 고려해서 만들지 않는다":"시멘트 창고 개구부는 채광과 통풍을 고려해 만들지 않습니다.","철골 용접은 주로 금속 전기 아크 용접이며 아크는 3,500℃의 고열을 낸다":"철골 용접은 주로 금속 전기 아크 방식이며, 이때 아크가 3,500℃에 이르는 열을 냅니다.","철근량이 많으면 측압은 작아진다":"철근량이 많으면 콘크리트 흐름이 방해되어 측압이 작아집니다.","철근 보호피막이 파괴돼 녹이 슬고 조강 시멘트를 쓰면 늦출 수 있다":"중성화되면 철근 보호피막이 깨져 녹이 슬고, 조강 시멘트를 쓰면 이를 늦출 수 있습니다.","철근에 진동을 주지 않고 슬럼프가 작으면 공기량 손실이 적다":"철근을 건드리면 안 되므로 철근에 진동을 주지 않고, 슬럼프가 작은 반죽은 공기량이 덜 빠집니다.","철재 외함을 접지하고 누전차단기를 설치하며 전력은 전문업자가 가설한다":"임시분전반은 철재 외함을 접지하고 누전차단기를 달며 전력은 전문업자가 가설합니다.","철화합물·망간화합물·소성온도에 영향을 받는다":"벽돌 색은 철화합물, 망간화합물, 소성온도에 따라 달라집니다.","청부는 목재 강도에 거의 영향이 없고 대다수 균은 CO2 80% 이상에서 발육이 중지된다":"대부분의 균은 CO2가 80% 이상이면 자라지 못하고, 청부는 목재 강도에 거의 영향이 없습니다.","청정·내구적이고 입도가 연속되며 강도가 경화 시멘트페이스트 이상이어야 한다":"골재는 깨끗하고 내구적이며 입도가 이어져야 하고 강도가 굳은 시멘트풀 이상이어야 합니다.","체계의 기능이지 유형이 아니다":"감지는 인간-기계 체계가 하는 기능이지 통합체계의 유형이 아닙니다.","체적팽창계수는 선팽창계수의 약 3배이며 단위가 W/m·K인 것은 열전도율이다":"체적팽창계수는 선팽창계수의 약 3배이고, 단위 W/m·K는 열전도율의 단위입니다.","체중분포·좌판 높이·좌판 깊이와 폭을 고려한다":"의자는 체중분포, 좌판 높이, 좌판 깊이와 폭을 고려해 설계합니다.","초당 10m 이상이면 철골작업을 중지한다":"철골작업은 풍속이 초당 10m에 이르면 하던 일을 멈춥니다.","초음파 탐상법으로 미소한 blow-hole은 검출하기 어렵다":"초음파 탐상법으로는 미소한 blow-hole을 찾아내기 어렵습니다.","최고경영자의 확고한 경영 자세·안전활동의 라인화·직장 자주활동 활성화이다":"최고경영자의 확고한 경영 자세, 안전활동의 라인화, 직장 자주활동 활성화를 무재해운동 추진의 세 요소로 봅니다.","최대 적재하중을 명시하고 승강용 사다리를 견고하게 설치한다":"이동식 비계에는 최대 적재하중을 적어 두고 오르내리는 사다리를 튼튼히 설치합니다.","최대 피치는 8d 이하이며 최소 피치는 3.0d가 아니다":"리벳 피치는 최대 8d 이하이며 최소 3.0d라는 설명은 맞지 않습니다.","최상부 작업 시 안전난간을 설치하고 이동 시에는 작업자가 비계에 탑승하지 않는다":"최상부에서 작업할 때는 안전난간을 설치하고 이동 중에는 작업자가 비계에 타지 않습니다.","추 63.5kg을 75cm 높이에서 낙하시킨다":"표준관입시험은 63.5kg 추를 75cm 높이에서 떨어뜨려 샘플러를 박습니다.","추락방지용 안전시설비에는 안전난간·개구부 덮개·안전대 걸이설비가 든다":"개구부 덮개나 안전대 걸이설비는 안전난간과 함께 추락을 막는 안전시설비에 들어갑니다.","추락 위험이 있는 곳에는 안전난간을 설치한다":"추락 위험이 있는 가설통로에는 안전난간을 설치합니다.","추락 위험 장소에는 안전난간을 설치하고 발판은 2 이상의 지지물에 고정한다":"발판은 두 곳 이상의 지지물에 묶어 고정하고, 추락 위험 장소에는 안전난간도 둡니다.","추재는 춘재보다 강도가 크고 수분이 많으면 강도가 작다":"추재는 춘재보다 단단하고 강하며, 수분이 많아지면 강도가 낮아집니다.","충전부 방호망·절연덮개는 직접접촉 방지이다":"충전부 방호망과 절연덮개는 직접접촉을 막는 방법입니다.","취급물질·화학설비 용량·온도 등이고 전원은 아니다":"정량적 평가 항목은 취급물질, 화학설비 용량, 온도 등이고 전원은 해당하지 않습니다.","측압은 바닥판·보 밑 거푸집의 설계하중이 아니다":"바닥판과 보 밑 거푸집은 위에서 누르는 힘만 견디면 되어 옆으로 미는 측압은 설계하중이 아닙니다.","치밀·견고해 타일·위생도기에 쓰며 시유타일은 바닥용으로 쓰지 않는다":"자기는 치밀하고 단단해 타일과 위생도기에 쓰며 시유타일은 바닥용으로 쓰지 않습니다.","치밀하고 외관이 미려하나 산성 우수에 침식돼 실외용으로 부적합하다":"대리석은 치밀하고 외관이 좋으나 산성비에 침식되어 바깥에 쓰기 어렵습니다.","치환·샌드드레인·페이퍼드레인이고 언더피닝은 아니다":"점성토 개량에는 치환, 샌드드레인, 페이퍼드레인이 쓰이고 언더피닝은 건물 기초 보강입니다.","침입도는 스트레이트가 크고 탄력성은 블론이 크다":"스트레이트는 침입도가 크게 나오고, 블론은 탄력이 더 좋습니다.","침하의 정도와 버팀대의 긴압(조임) 정도이다":"흙막이 지보공은 침하의 정도와 버팀대의 긴압(조임) 정도를 점검합니다.","컨시스턴시는 물의 양에 따른 반죽의 질기, 워커빌리티는 타설 난이도와 재료분리 정도이다":"컨시스턴시는 물의 양에 따른 반죽의 질기이고, 워커빌리티는 치기 쉬움과 재료분리 정도입니다.","컨시스턴시를 측정하며 시험통은 윗지름 10cm·아래지름 20cm·높이 30cm이다":"슬럼프시험은 컨시스턴시를 재며 시험통은 윗지름 10cm, 아래지름 20cm, 높이 30cm입니다.","케이싱관과 벤토나이트액도 피어기초와 관계 있다":"케이싱관과 벤토나이트액도 피어기초 굴착에 쓰이므로 관계가 있습니다.","코아·필터층을 설치하고 상재하중이나 주동토압을 키우지 않는다":"토류벽 선단에는 코아·필터층을 설치하고 상재하중과 주동토압을 키우지 않아야 합니다.","코킹재·퍼티·실링재이고 트래버틴은 아니다":"실재에는 코킹재, 퍼티, 실링재가 있고 트래버틴은 석재라 실재가 아닙니다.","코펜하겐 리브·연질 섬유판·코르크 보드":"음을 조절하는 목재 제품에는 코펜하겐 리브, 연질 섬유판, 코르크 보드가 있습니다.","콘에 같은 양의 3층으로 나누어 25회씩 다지며 채운다":"슬럼프콘에는 같은 양씩 세 층으로 나누어 채우고 층마다 25회 다집니다.","콘크리트 강도는 물시멘트비에 크게 좌우되고 압축강도가 역학적 기능을 대표한다":"물시멘트비가 콘크리트 강도를 크게 좌우하고, 역학적 기능은 압축강도로 대표됩니다.","콘크리트는 수산화칼슘 때문에 알칼리성이고 목재 섬유포화점은 함수율 30%이다":"수산화칼슘 때문에 콘크리트는 알칼리성이며 목재의 섬유포화점은 함수율 30%입니다.","콘크리트 중량·거푸집 자중·작업자 중량":"연직하중에는 콘크리트 중량, 거푸집 자중, 작업자 중량이 들어갑니다.","크레인·곤돌라·리프트·승강기가 있다":"양중기에는 크레인, 곤돌라, 리프트, 승강기가 있습니다.","크레인 방호장치는 과부하방지장치·비상정지장치·권과방지장치이다":"과부하방지장치, 비상정지장치, 권과방지장치가 크레인의 방호장치로 꼽힙니다.","크롬·니켈이 주성분이고 탄소량이 적어 내식성이 우수하다":"크롬·니켈이 주성분이고 탄소량이 적어서 스테인리스강은 녹이 잘 슬지 않습니다.","큰 소리로 음절을 길게 말하며 음성주파수 변화가 크다":"우수한 화자는 큰 소리로 음절을 길게 말하고 음성주파수 변화가 큽니다.","타설(이어붓기) 속도가 빠를수록 측압이 크다":"타설(이어붓기) 속도가 빠르면 콘크리트가 굳기 전 쌓이는 높이가 커져 측압이 큽니다.","타설속도가 빠르고 슬럼프가 크고 단면이 클수록 측압이 크다":"타설을 빨리 하고 슬럼프와 단면이 클수록 거푸집이 받는 측압이 커집니다.","타설 온도가 낮을수록 측압이 크고 높을수록 작다":"타설 온도가 낮으면 늦게 굳어 측압이 오래 유지되고, 온도가 높으면 측압이 작아집니다.","타워크레인과 윈치도 철골 설치에 쓴다":"타워크레인과 윈치도 철골 설치에 쓰는 장비입니다.","탄소가 늘면 강도·경도가 오르고 연신율은 감소한다":"탄소가 늘면 강의 강도와 경도가 오르고 연신율은 줄어듭니다.","탈수다짐법·치환법·약액주입법이 있다":"지반개량에는 탈수다짐법, 치환법, 약액주입법이 있습니다.","태도조사법은 문답법이고 조직·구성원의 성과 비교·분석은 효용이 아니다":"문답법인 태도조사법과 달리 조직·구성원의 성과 비교·분석은 모랄 서베이의 효용이 아닙니다.","터널 건설과 최대지간 50m 이상 교량 공사도 대상이다":"교량은 최대지간이 50m 이상이면 터널과 마찬가지로 유해위험방지계획서 제출 대상입니다.","터널지보공·록볼트 설치와 부석 제거로 한다":"낙반은 터널지보공과 록볼트를 설치하고 부석을 제거해 막습니다.","토기·도기·석기·자기 순으로 소성온도가 높고 도기의 흡수성은 석기보다 크다":"소성온도는 토기, 도기, 석기, 자기 순으로 높아지며 도기는 석기보다 물을 많이 흡수합니다.","토사 굴착·운반·하역에 쓰고 다짐은 하지 않는다":"스크레이퍼는 흙을 파고 싣고 나르고 부리는 기계이며 다짐 기능은 없습니다.","토석 강도 저하는 외적 원인이 아니다":"토석 강도 저하는 흙 내부에서 생기는 내적 원인이어서 외적 원인이 아닙니다.","통제기기는 계기지침과 일치하고 복잡·정밀 조절에는 멀티로테이션 컨트롤을 쓴다":"통제기기는 계기 지침과 방향을 맞추고 복잡하고 정밀한 조절에는 멀티로테이션 컨트롤을 씁니다.","통제표시비 설계 시 계기 크기·조작시간·방향성·공차·목측거리를 고려한다":"통제표시비 설계 때는 계기 크기, 조작시간, 방향성, 공차, 목측거리를 고려합니다.","통풍이 안 되고 습기가 많은 곳은 보관 장소로 부적합하다":"통풍이 안 되고 습기가 많은 곳은 안전대 보관 장소로 맞지 않습니다.","통풍이 잘되는 곳에 40℃ 이하로 보관하고 용해 아세틸렌은 세워 둔다":"가스용기는 40℃ 이하로 통풍이 잘되는 곳에 두고, 용해 아세틸렌 용기는 눕히지 않고 세웁니다.","투기성이 큰 것은 단열재 조건이 아니다":"투기성이 크면 공기가 드나들어 단열이 떨어지므로 단열재가 갖출 조건이 아닙니다.","투수계수는 현장시험으로 구하고 간극이 작을수록 감소한다":"투수계수는 현장에서 시험해 구하고, 간극이 좁아질수록 값이 작아집니다.","트임새 모양·모아 대기법·구속법이다":"용접 착수 전에는 트임새 모양, 모아 대기법, 구속법을 검사합니다.","특별교육·관리감독자 정기교육·채용 시 교육이 있고 안전관리자 신규·보수교육은 아니다":"사업 내 교육의 종류는 특별교육, 관리감독자 정기교육, 채용 시 교육이며 안전관리자 신규·보수교육은 별도입니다.","틈새 없는 거푸집을 쓰고 이음치기를 피하며 양생을 충분히 하고 긴결철물은 누수가 없어야 한다":"틈새 없는 거푸집을 쓰고 이음치기를 피하며 양생을 충분히 하고 긴결철물에서 물이 새지 않아야 합니다.","파블로프 조건반사설의 원리는 강도·시간·계속성·일관성의 원리이다":"파블로프 조건반사설의 학습원리는 강도, 시간, 계속성, 일관성입니다.","파손 미보수·강도 미달·인체 이상 무게 낙하물 충격을 받은 망은 쓰지 않는다":"손상을 고치지 않은 망, 강도가 모자란 망, 사람 무게 이상 물체의 충격을 받은 망은 쓰지 않습니다.","팔꿈치 높이보다 약간 높게 하고 정밀·장기간 작업은 좌식작업대가 낫다":"정밀 작업대는 팔꿈치 높이보다 약간 높게 하고 정밀하고 오래 하는 작업은 앉아서 하는 편이 낫습니다.","페놀·멜라민·알키드수지는 열경화성이고 아크릴수지는 아니다":"아크릴수지는 열을 가하면 다시 물러지는 열가소성이고, 페놀·멜라민·알키드수지가 열경화성입니다.","평가는 5단계에 들지 않는다. 추론(Reasoning)도 5단계가 아니다":"평가와 추론(Reasoning)은 하인리히 5단계에 들지 않습니다.","평균기온 20℃ 이상이면 재령 3일, 10~20℃ 미만이면 재령 4일 이상이다":"거푸집은 20℃ 이상 평균기온에서 재령 3일, 10~20℃ 미만에서 재령 4일 이상일 때 해체합니다.","평균 인화점은 약 240℃이고 수분이 많을수록 열전도율이 높다":"목재의 평균 인화점은 약 240℃이며 수분이 많아질수록 열이 더 잘 전해집니다.","포화 폴리에스테르수지는 알키드수지로 도료에 쓰며 불포화는 유리섬유로 보강해 FRP를 만든다":"도료용 알키드수지는 포화 폴리에스테르에서 나오고, 불포화 쪽에 유리섬유를 넣으면 FRP가 됩니다.","폭 30cm 이상이고 다리 부분에 미끄럼 방지장치를 한다":"이동식 사다리는 폭 30cm를 넘겨야 하고 다리에는 미끄러지지 않게 장치를 붙입니다.","폼타이·플랫타이·컬럼밴드이고 동바리는 아니다":"긴결재에는 폼타이, 플랫타이, 컬럼밴드가 있고 동바리는 긴결재가 아닙니다.","표시상 제약으로 작업 세분화에 한계가 있고 경험이 적은 사람이 쉽게 쓰는 것은 아니다":"표시상 제약으로 작업을 잘게 나누는 데 한계가 있고 경험이 적은 사람이 쉽게 쓰는 방식은 아닙니다.","표적과 주변 휘도가 같을 때 최대이고 휘도가 같으면 색상은 영향이 없다":"표적과 주변의 휘도가 같을 때 VFF가 최대가 되고, 이때는 색상이 달라도 영향이 없습니다.","표준관입시험은 개량공법이 아니고 고결공법은 강제압밀이 아니다":"표준관입시험은 지반을 조사하는 시험이라 개량공법이 아니고, 고결공법도 강제압밀 공법이 아닙니다.","풍화된 시멘트는 응결이 늦고 비중이 작아지며 강도가 감소한다":"공기 중 습기를 먹은 시멘트는 응결이 느려지고 비중과 강도가 함께 떨어집니다.","플로어링 보드·파키트리 보드·파키트리 블록이다":"마루판에는 플로어링 보드, 파키트리 보드, 파키트리 블록이 있습니다.","피부 온도 상승·발한 증가·심박출량 증가를 일으킨다":"고온 스트레스는 피부 온도 상승, 발한 증가, 심박출량 증가를 일으킵니다.","피어기초 공사는 트레미관을 쓴다":"피어기초 공사에서는 콘크리트를 물속에 치는 트레미관을 사용합니다.","필요한 사항의 동일성을 식별하고 프로그램 해석·평가를 한다":"시스템 안전업무는 필요한 사항의 동일성을 식별하고 프로그램을 해석하고 평가합니다.","하나만 고장 나도 계가 고장이고 수명은 가장 짧은 요소로 정해진다":"직렬계는 하나만 고장 나도 전체가 멈추고 수명은 가장 짧은 요소가 정합니다.","하단에는 미끄럼 방지장치를 하고 지주 간 보조부재를 둔다":"말비계 하단에는 미끄럼 방지장치를 하고 지주 사이에 보조부재를 둡니다.","하루 10회 이상 25kg 이상 들기, 2시간 이상 쪼그린 자세, 4시간 이상 키보드·마우스 조작이다":"들기 10회 이상 25kg 이상, 쪼그린 자세 2시간 이상, 키보드·마우스 조작 4시간 이상이 하루 부담작업 기준입니다.","하루 평균기온 4℃ 이하가 예상되면 한중콘크리트로 시공한다":"일 평균기온이 4℃ 이하로 떨어질 것 같으면 한중콘크리트 방식을 씁니다.","하역장치·디퍼·버킷은 지면 가장 낮은 위치로 내리며 마스트는 시야를 넓히지 않는다":"하역장치와 버킷을 지면 가장 낮게 내려 두며 마스트로 시야를 넓히는 것은 이 조치가 아닙니다.","학습의 정도·방법·태도·시간적 간격이고 학습의 평가는 아니다":"전이 조건에는 학습의 정도, 방법, 태도, 시간적 간격이 있고 학습의 평가는 아닙니다.","학습 직후 복습하면 기억 파지 효과가 높고 사고력을 요하는 내용이 파지가 좋다":"학습 직후 복습하면 기억 파지 효과가 높고 사고력이 필요한 내용이 더 잘 남습니다.","학습평가 도구의 기본 기준은 타당도·신뢰도·객관도이다":"학습평가 도구는 타당도, 신뢰도, 객관도를 기본 기준으로 삼습니다.","한 꼬임에서 소선이 10% 이상 절단된 것은 사용금지이며 기준은 7%·20%·5%가 아니다":"한 꼬임에서 소선이 10% 이상 끊어진 로프는 사용을 금하며 기준은 7%, 20%, 5%가 아닙니다.","한 장소에 오래 고정해 작업하지 않으며 식염을 많이 섭취하는 것은 고온 작업 대책이다":"고온 작업 대책으로 한 장소에 고정해 오래 일하지 않고 식염을 많이 섭취합니다.","함수량은 흙 속 물의 중량이고 투수량이 큰 모래는 투수계수가 크다":"함수량은 흙 속 물의 무게이고 물이 많이 통하는 모래는 투수계수가 큽니다.","함수율이 섬유포화점 이상이면 강도 변화가 거의 없고 이하부터 수축한다":"함수율이 섬유포화점 위에서는 강도가 거의 변하지 않고 그 아래로 내려가야 수축이 시작됩니다.","합성수지는 가공이 쉽고 내수성이 좋으나 내화성이 크지 않다":"합성수지는 가공이 쉽고 물에 강하나 불에는 약해 내화성이 크지 않습니다.","항타기는 양중기가 아니고 리프트는 승강기가 아니다":"항타기는 양중기가 아니고 리프트는 승강기와 다른 양중기입니다.","해석 영역이 물체에 한정되어 인적 원인 해명이 곤란하고 서브시스템은 FTA가 더 실제적이다":"FMEA는 물체에만 해석이 한정돼 사람이 낸 원인을 밝히기 어렵고, 서브시스템 분석은 FTA가 더 현실적입니다.","해체는 순서대로 하고 관계자 외 출입을 금하며 자재는 달줄·달포대로 오르내린다":"거푸집 해체는 정해진 순서로 하고 관계자만 출입하게 하며 자재는 달줄이나 달포대에 담아 오르내립니다.","핵심 요소인 불안전 행동·상태를 제거하면 사고가 일어나지 않는다":"불안전 행동과 상태가 핵심 요소여서 이를 없애면 사고가 일어나지 않습니다.","행위(순서) 관점의 분류이지 원인별 분류가 아니다":"Sequential error는 행위(순서) 관점의 분류이지 원인별 분류가 아닙니다.","허리 부분은 요부 전만을 유지하고 좌판과 등받이 각도는 90~105°이며 앞 모서리는 5cm 정도 낮다":"좌판과 등받이는 90~105°로 벌리고 앞 모서리는 5cm쯤 낮추며 허리는 요부 전만을 지키게 설계합니다.","현상 대응력에 한계가 있고 초점에서 멀어질수록 희미해진다":"의식은 초점에서 멀어질수록 희미해져 현상 대응력에 한계가 있습니다.","현장 건립 순서와 공장 제작 순서를 일치시킨다":"현장 건립 순서와 공장 제작 순서를 일치시켜야 부재가 차례대로 반입됩니다.","혈압·부정맥·심박수이며 혈액성분은 아니다":"생리적 스트레인 척도는 혈압, 부정맥, 심박수이며 혈액성분은 해당하지 않습니다.","형상·지질 및 지층의 상태는 사전조사 항목이지 정기점검 항목이 아니다":"형상·지질 및 지층 상태는 정기점검이 아니라 공사 전 사전조사에서 봅니다.","형태·구성·위치로 부호를 구분한다":"부호는 형태, 구성, 위치로 구분합니다.","화염에 노출되면 균열이 생겨 내화성이 높다고 할 수 없다":"화강암은 불에 닿으면 균열이 생기므로 내화성이 높다고 할 수 없습니다.","확률 0.25인 뒷면은 2.0bit이다":"확률이 0.25인 뒷면의 정보량은 2.0bit입니다.","확률 0.5인 앞면은 1.0bit이다":"확률이 0.5인 앞면의 정보량은 1.0bit입니다.","환경(E)이며 B와 f는 아니다":"인간관계 요인에 해당하는 것은 환경(E)이며 B와 f는 아닙니다.","환경조건 부적당·주의 부족·능력 부족이다":"인간 실수의 요인은 환경조건 부적당, 주의 부족, 능력 부족입니다.","활동(sliding)·전도(overturning)·지반 지지력이다":"옹벽 안정 검토는 활동(sliding), 전도(overturning), 지반 지지력을 봅니다.","활엽수는 침엽수보다 일반적으로 비중이 크다":"활엽수는 침엽수에 비해 대체로 비중이 큽니다.","회반죽은 기경성이며 질석모르타르는 내화피복용, 바라이트 모르타르는 방사선 방호용이다":"방사선을 막는 데는 바라이트 모르타르, 불을 막는 피복에는 질석모르타르를 쓰고 회반죽은 기경성입니다.","훈련 비용 증가는 가치가 아니다":"훈련 비용이 늘어나는 것은 인간공학이 주는 가치가 아닙니다.","휘광원 주위를 밝게 해 휘도비를 줄인다":"휘광원 주위를 밝게 하면 휘도비가 줄어 눈부심이 덜합니다.","흘린 콘크리트는 청소하고 지나친 진동기 사용은 재료분리를 일으켜 금한다":"흘린 콘크리트는 청소하고, 진동기를 지나치게 쓰면 재료분리가 생겨 금합니다.","흙막이 벽에 미치는 간극수압은 Piezo meter로 계측한다":"Piezo meter는 흙막이 벽에 작용하는 간극수압을 재는 계측기입니다.","흙막이벽의 타입 깊이를 늘려 방지한다":"흙막이벽을 더 깊이 박으면 보일링을 막을 수 있습니다.","흙막이 벽체 안팎의 토사 중량차나 근입장 부족으로 생긴다":"흙막이 벽체 안팎의 토사 무게 차이나 근입장 부족 때문에 히빙이 생깁니다.","흙막이 외부 지반면을 진동·가압하거나 배면 수위와 굴착저면의 수위차를 키우면 안 된다":"흙막이 바깥 지반을 흔들거나 누르거나 배면 수위와 굴착저면 수위차를 키우면 안 됩니다.","희석액으로 계량하며 공기량은 온도가 높을수록 감소한다":"AE제는 희석한 액으로 계량하고 공기량은 온도가 높을수록 줄어듭니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
